: \"ZY010000473008\", \"正常值上限\": \"0.06\", \"正常值下限\": \"0\"}, {\"单位\": \"%\", \"检验ID\": \"XN90002022070692\", \"检测值\": \"1\", \"报告时间\": \"2022-07-06 08:55:20\", \"检验时间\": \"2022-07-06 08:55:20\", \"检验结果\": \"1%\", \"检验详情\": \"1%\", \"检验项目\": \"血常规(六分类)\", \"申请时间\": \"2022-07-05 23:23:40\", \"住院流水号\": \"ZY010000473008\", \"正常值上限\": \"0.5\", \"正常值下限\": \"0\"}, {\"单位\": \"xxx\", \"检验ID\": \"免疫录20220701976\", \"检测值\": \"阴性(-)\", \"报告时间\": \"2022-07-01 14:49:06\", \"检验时间\": \"2022-07-01 14:49:06\", \"检验结果\": \"xxx\", \"检验详情\": \"xxx\", \"检验项目\": \"传染病筛查快速检测(急诊专用)\", \"申请时间\": \"2022-07-01 13:45:19\", \"住院流水号\": \"ZY010000473008\", \"正常值上限\": \"xxx\", \"正常值下限\": \"阴性\"}, {\"单位\": \"xxx\", \"检验ID\": \"培养录2022072028217\", \"检测值\": \"xxx\", \"报告时间\": \"2022-07-25 10:23:38\", \"检验时间\": \"2022-07-25 10:23:38\", \"检验结果\": \"xxx\", \"检验详情\": \"xxx\", \"检验项目\": \"xxx\", \"申请时间\": \"2022-07-19 15:51:48\", \"住院流水号\": \"ZY010000473008\", \"正常值上限\": \"xxx\", \"正常值下限\": \"xxx\"}], \"用药信息\": {\"手术用药\": [], \"治疗用药\": []}, \"病理报告\": [], \"日常病程记录\": [{\"文本\": \"今日查房，患者无畏寒发热，无腹痛腹泻等不适，饮食睡眠可，二便正常。查体：骶尾部可见1大小约2*1cm伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织，四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。治疗上予以改善循环、预防深静脉血栓、促进骨愈合、抗感染、抗骨质疏松、补充蛋白等治疗。\", \"创建时间\": \"2022-07-04\"}, {\"文本\": \"患者无不适主诉，饮食睡眠可，二便正常。查体：神志清，精神可，食欲食量一般，心肺腹查体未见明显异常，骶尾部可见1大小约2*1cm伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织，四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。治疗上予以预防深静脉血栓、伤口清创换药、康复新液等治疗。\", \"创建时间\": \"2022-07-13\"}, {\"文本\": \"患者无不适主诉，饮食睡眠可，二便正常。查体显示神志清，精神可，食欲食量一般，心肺腹查体未见明显异常，骶尾部有伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织。四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。患者及家属要求出院，已办理出院手续，出院后需继续进行骶尾部创面修复和脑梗死康复治疗。\", \"创建时间\": \"2022-07-20\"}], \"首次病程记录\": {\"创建时间\": \"2022-07-01 13:36:33\", \"初步诊断\": \"1.骶尾区压疮并感染 2.2型糖尿病3.2型糖尿病伴有周围循环并发症4.2型糖尿病伴有神经的并发症5.脑梗死6.高血压病3级（极高危）7.低蛋白血症\", \"拟诊讨论\": \"诊断明确无需鉴别诊断。\", \"病例特点\": \"患者诉1月余前无明显诱因出现骶尾部皮肤溃烂，伴有渗液、疼痛，无畏寒发热，无胸闷气促等不适。\", \"诊断依据\": \"患者钟前龙，男，81岁，因“骶尾部流脓渗液1月余”入院。既往糖尿病病史10余年，规律给予胰岛素降糖治疗，高血压病史5年余，给予硝苯地平降压治疗，体格检查： 骶尾部可见1大小约2*1cm伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织，四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。辅助检查：2022-07-01 血常规(五分类):白细胞计数 11.53×10^9/L↑、中性粒细胞比率 71.2%↑、血红蛋白 112g/L↓；2022-07-01 急诊生化全套(套):血糖 11.48mmol/L↑、肌酐 164.3μmol/L↑、超敏C反应蛋白 42.72mg/L↑、丙氨酸氨基转移酶 72U/L↑、天冬氨酸氨基转移酶 52U/L↑、白蛋白 27.9g/L↓；\", \"诊疗计划\": \"1、血常规、血型、凝血四项+纤维蛋白原降解产物两项、生化全套、传染病筛查、降钙素原；\\n    2、床边心电图、胸部CT等\", \"鉴别诊断\": \"文本中未提及该内容\"}, \"主任医师首次查房记录\": {\"创建时间\": \"2022-07-03 09:05\", \"注意事项\": \"文本中未提及该内容\", \"诊疗意见\": \"文本中未提及该内容\", \"诊疗计划\": \"程少文副主任医师查房后指示：改善循环、预防深静脉血栓、康复新液湿敷创面，抗感染、抗骨质疏松、补充蛋白等治疗。\", \"主任医生查房\": \"程少文副主任医师查房记录\\n程少文副主任医师今日查房，患者无畏寒发热，无胸闷气促等不适，饮食睡眠可，二便正常。查体：骶尾部可见1大小约2*1cm伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织，四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。\", \"对病情的分析\": \"文本中未提及该内容\", \"补充病史与体征\": \"文本中未提及该内容\"}, \"主治医师首次查房记录\": {\"诊断\": \"文本中未提及该内容\", \"创建时间\": \"2022-07-02 09:03\", \"诊断依据\": \"2022-07-01 血常规(五分类):白细胞计数 11.53×10^9/L↑、中性粒细胞比率 71.2%↑、血红蛋白 112g/L↓；2022-07-01 急诊生化全套(套):血糖 11.48mmol/L↑、肌酐 164.3μmol/L↑、超敏C反应蛋白 42.72mg/L↑、丙氨酸氨基转移酶 72U/L↑、天冬氨酸氨基转移酶 52U/L↑、白蛋白 27.9g/L↓\", \"诊疗计划\": \"查房后指示：暂予改善循环、创面换药等治疗，完善相关检查后拟进一步治疗。\", \"鉴别诊断\": \"文本中未提及该内容\", \"主治医生查房\": \"曾允富主治医师查房，病情分析如下：患者钟前龙，男，81岁，因“骶尾部流脓渗液1月余”入院。既往糖尿病病史10余年，规律给予胰岛素降糖治疗，高血压病史5年余，给予硝苯地平降压治疗，体格检查： 骶尾部可见1大小约2*1cm伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织，四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。\", \"补充病史和体征\": \"患者钟前龙，男，81岁，既往糖尿病病史10余年，规律给予胰岛素降糖治疗，高血压病史5年余，给予硝苯地平降压治疗，体格检查： 骶尾部可见1大小约2*1cm伤口，局部皮温增高，流脓渗液，伴有坏死脂肪组织，四肢肌力2级，肌张力正常，生理反射存在，病理反射未引出。\"}}','2026-06-30 06:17:29.300640');
