名称\": \"5%GS\"}], \"检查报告\": [{\"检查ID\": \"xxx\", \"图像分析\": \"xxx\", \"报告时间\": \"xxx\", \"检查内容\": \"xxx\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-04 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-04 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"泌尿系(彩超),腹部(彩超),妇科(彩超),(浅表)阑尾(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"xxx\", \"报告时间\": \"2022-07-04 08:55:36\", \"检查内容\": \"xxx\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-04 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-04 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"泌尿系(彩超),腹部(彩超),妇科(彩超),(浅表)阑尾(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"xxx\", \"报告时间\": \"xxx\", \"检查内容\": \"xxx\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-11 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-11 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"术中超声(彩超),胸腔穿刺置管引流术(不含引流管)(组套)(超声科)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"超声引导下左侧胸腔积液穿刺置管引流术。\\r\\n保持伤口干燥一天，避免激烈活动三天。\\r\\n不适时请我科随诊。\", \"报告时间\": \"2022-07-11 15:10:38\", \"检查内容\": \"坐位扫查：\\r\\n选左侧胸腔积液为穿刺目标，超声定位穿刺点后消毒铺巾，2%利多卡因逐层麻醉至胸膜，用“Y”型穿刺针（18Ga）在超声引导下进针，针尖到达液性区内，经穿刺针管腔置入导丝，拔出穿刺针，用扩张管（9Fr）沿导丝局部扩张，拔出扩张管，置入舒贝康（CF-B 12Ga×20cm）一次性中心静脉导管15cm，抽出黄色液体200ml，接引流袋，引流通畅，缝合、固定引流管。\\r\\n术程顺利，复查超声，术区无出血，穿刺后半个小时观察病人无不适，安返病房。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-11 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-11 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"术中超声(彩超),胸腔穿刺置管引流术(不含引流管)(组套)(超声科)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"双侧下肢静脉未见异常。\", \"报告时间\": \"2022-07-01 21:44:51\", \"检查内容\": \"双侧股总静脉、股深静脉、股浅静脉、腘静脉、胫前静脉、胫后静脉、腓静脉、大隐静脉内径正常，管腔内未见异常回声，探头加压可压闭，CDFI显示彩流充盈好。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-01 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-01 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"腹部大血管(彩超),下肢静脉(双侧)(彩超),心脏超声(组套)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"急诊报告：\\r\\n主动脉瓣前向流速稍增快。\\r\\n左室舒张功能减退；左室收缩功能测值正常。\\r\\n二尖瓣、三尖瓣、肺动脉瓣轻度反流。\\r\\n心率增快。\\r\\n心包腔未见积液。\\r\\n（胸腔积液。）\\r\\n\\r\\n提示：本报告为急诊报告，如需了解心脏详细情况，请平诊复查。\", \"报告时间\": \"2022-07-01 21:44:27\", \"检查内容\": \"左侧卧位扫查：\\r\\n2D及M型：各房室腔无显著扩大。室壁运动未见异常。主动脉根部不宽，内未见异常回声。心包腔未见分离性液性区。心率：102次/分。\\r\\n\\r\\n心功能测值：EDV：86ml，ESV：33ml，SV：53ml，EF：61%，FS: 32％。MV E/A＜1。\\r\\n\\r\\nCDFI及PW/CW/TDI特征：\\r\\n主动脉瓣前向血流速度稍增快，峰速1.94/s。\\r\\n二尖瓣见少量反流。\\r\\n三尖瓣见少量反流。\\r\\n肺动脉瓣见少量反流。\\r\\n（胸腔见游离液性区。）\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-01 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-01 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"腹部大血管(彩超),下肢静脉(双侧)(彩超),心脏超声(组套)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"急诊报告：\\r\\n腹主动脉可显示部分未见异常。\\r\\n下腔静脉可显示部分未见明显血栓。\\r\\n\\r\\n提示：本次检查为急诊超声检查，仅提供急症相关信息，如需了解相关腹部大血管详细情况请平诊复查。\", \"报告时间\": \"2022-07-01 21:57:54\", \"检查内容\": \"因腹腔胀气及巨大瘤体遮挡，腹腔胀气明显，腹部大血管仅可探及部分腹主动脉及下腔静脉。\\r\\n可显示腹主动脉内径正常，管腔血流通畅，内未见明显异常回声。\\r\\n可显示下腔静脉、门静脉、肠系膜上静脉、脾静脉内径正常，管腔内未见低弱回声充填，CDFI显示血流充盈可。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-01 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-01 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"腹部大血管(彩超),下肢静脉(双侧)(彩超),心脏超声(组套)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"1、腹盆腔巨大囊实性肿块，考虑恶性肿瘤（多为卵巢囊腺癌，多来源于左侧卵巢），供血动脉来源于左侧卵巢动脉；建议：临床随诊复查或可结合MRI增强检查。\\n2、腹盆腔少量积液。\\n3、子宫增大，子宫实性结节，考虑子宫肌瘤可能，请结合彩超或MRI检查。肝左内叶小钙化灶。左肾小囊肿。\\n4、附见：左侧胸膜腔中量积液伴左肺下叶膨胀不全。右侧胸腔少量积液。所见双肺少量渗出灶伴右肺明显。心包稍厚。\", \"报告时间\": \"2022-07-05 21:42:50\", \"检查内容\": \"腹盆腔巨大囊实性肿块，大小约20cm×12cm×19cm，肿块内可见多房分隔，囊壁厚薄不均伴可见多个壁结节，增强扫描实性成分轻度强化，肿块推压部分肠管移位。CTA显示肿块供血动脉来源于左侧卵巢动脉。\\n    子宫增大伴可见一实性结节，结节直径约41mm。右侧附件观察不清。\\n    肝左内叶钙化灶。胆囊、胰腺、脾脏平扫及增强未见异常密度灶和未见明显强化灶。左肾下段实质见一囊性病灶，直径约5mm，增强无强化。右肾盂输尿管轻度积液扩张。腹腔和盆腔少量积液。盆壁皮下弥漫性水肿。扫描范围内：胃腔潴留物稍多，部分结肠多发积气和肠管内容物较多。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-05 15:16:19\", \"检查部位\": \"其他\", \"检查项目\": \"计算机X线断层摄影（CT）\", \"申请时间\": \"2022-07-04 14:58:08\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"97693771-F00000086741-螺旋CT上腹部增强(组套)(第一部位)-270.00\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"超声引导下右侧胸腔积液穿刺置管引流术。\\r\\n保持伤口干燥一天，避免激烈活动三天。\\r\\n不适时请我科随诊。\", \"报告时间\": \"2022-07-20 17:36:55\", \"检查内容\": \"选右侧胸腔积液为穿刺目标，超声定位穿刺点后消毒铺巾，2%利多卡因逐层麻醉至胸膜，用“Y”型穿刺针（18Ga）在超声引导下进针，针尖到达液性区内，经穿刺针管腔置入导丝，拔出穿刺针，用扩张管（9Fr）沿导丝局部扩张，拔出扩张管，置入舒贝康（CF-B 12Ga×20cm）一次性中心静脉导管13cm，接引流袋，引流通畅，缝合、固定引流管。\\r\\n术程顺利，复查超声，引流出淡黄色250ml，复查超声提示胸腔未见明显积液，术区无出血。\\r\\n穿刺后半个小时观察病人无不适，安返病房。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-20 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-20 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"术中超声(彩超),胸腔穿刺术(不含穿刺针)(组套)(超声科)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"盆腹腔巨大混合性包块，考虑卵巢恶性肿瘤可能性大。\\r\\n腹腔极少量积液。\\r\\n子宫未见明显异常。\", \"报告时间\": \"2022-07-13 12:16:38\", \"检查内容\": \"子宫呈前位，宫体大小形态基本正常。\\r\\n内膜显示满意。\\r\\n双侧卵巢显示不清。\\r\\n盆腹腔见一巨大混合性包块，大小约260mm×217mm×135mm，边界清，内部以实性为主，内回声不均匀，内见不规则液性区及带状分隔，CDFI显示其内实性部分及分隔带上见杆状彩流信号，PW可探及中阻力动脉频谱，RI=0.59。\\r\\n盆腔未见游离液性区。\\r\\n腹腔见少量液性区，最深处约12mm。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-13 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-13 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"妇科(彩超),胸部(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"双侧胸腔积液（少-中量）。\", \"报告时间\": \"2022-07-13 12:16:50\", \"检查内容\": \"左侧胸腔可见成片液性区，液体前后径约35mm，上下径约58mm，内见留置管回声。\\r\\n右侧胸腔可见成片液性区，液体前后径约46mm，上下径约55mm。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-13 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-13 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"妇科(彩超),胸部(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"1、盆-腹腔巨大囊实性肿块，考虑卵巢囊腺癌可能性大。\\n2、子宫右前壁小结节，考虑子宫肌瘤；宫腔少量积血。\\n3、盆腔少量积液。\", \"报告时间\": \"2022-07-11 05:36:26\", \"检查内容\": \"盆-腹腔内可见一巨大囊实性肿块，大小约19.8cm×21.5cm×12.7cm，以囊性为主，病变呈多房，内可见分隔，壁不规则增厚并可见多发壁结节及肿块，病灶信号T1WI呈低信号，T2WI呈高信号，增强扫描囊壁、分隔及实性成分强化。\\n    子宫右前壁见一长T1信号小结节，大小约7mm×5mm，宫腔内见少量短T1信号影，增强无明显强化。\\n    膀胱充盈，未见明显异常。盆腔内未见肿大淋巴结。盆腔少量液体信号影。所见骨质信号均匀。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-09 15:11:20\", \"检查部位\": \"其他\", \"检查项目\": \"核磁共振成像（NMR）\", \"申请时间\": \"2022-07-08 10:16:09\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"97854548-F00000072552-磁共振盆腔(子宫及附件/膀胱)平扫+增强-921.00\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"目前未见明确阑尾炎声像。\", \"报告时间\": \"2022-07-04 19:19:56\", \"检查内容\": \"全腹肠管未见扩张。\\r\\n右下腹未见明显肿大阑尾回声。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-04 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-04 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"妇科(彩超),(浅表)阑尾(彩超),泌尿系(彩超),腹部(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"双肾、双侧输尿管、膀胱未见异常。\", \"报告时间\": \"2022-07-04 19:20:10\", \"检查内容\": \"双肾形态大小正常，包膜光滑，肾实质及肾窦未见异常回声。\\r\\n双侧输尿管无扩张。\\r\\n膀胱充盈，壁光滑，腔内未见异常回声。\\r\\nCDFI：上述脏器未见异常彩流信号。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-04 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-04 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"妇科(彩超),(浅表)阑尾(彩超),泌尿系(彩超),腹部(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"腹腔积液。\\r\\n肝脏、餐后胆囊、脾脏、胰腺未见异常。\", \"报告时间\": \"2022-07-04 19:22:46\", \"检查内容\": \"肝脏形态正常，大小正常值范围，肝脏实质呈均匀等回声，肝内血管内径正常值范围，内未见异常回声。\\r\\n餐后胆囊体积缩小，内未见异常回声。\\r\\n肝内外胆管未见增宽，内未见异常回声。\\r\\n脾脏形态正常，大小正常值范围，实质呈均匀等回声。\\r\\n胰腺形态正常，大小正常值范围，主胰管内径正常值范围，实质呈均匀等回声。\\r\\nCDFI显示上述器官均未见异常彩流信号。\\r\\n右肝下缘及肝肾间隙可见游离性液性区，分别深约4mm、5mm。\\r\\n左下腹部及右下腹可见游离性液性区，分别深约18mm、12mm。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-04 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-04 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"妇科(彩超),(浅表)阑尾(彩超),泌尿系(彩超),腹部(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"盆腹腔巨大混合性包块，考虑卵巢囊腺肿瘤。\", \"报告时间\": \"2022-07-04 19:23:28\", \"检查内容\": \"盆腹腔见一巨大混合性包块，大小约188mm×213mm×132mm，边界清，内回声不均匀，内见不规则液性区及带状分隔，CDFI显示其内见杆状彩流信号，可探及静脉频谱及低阻血流信号，RI=0.34。\\r\\n子宫及双侧卵巢显示不清。\\r\\n盆腔未见游离液性区。\", \"检查描述\": \"xxx\", \"检查时间\": \"2022-07-04 00:00:00\", \"检查部位\": \"xxx\", \"检查项目\": \"超声检查\", \"申请时间\": \"2022-07-04 00:00:00\", \"住院流水号\": \"ZY010000473043\", \"检查子类型\": \"妇科(彩超),(浅表)阑尾(彩超),泌尿系(彩超),腹部(彩超)\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"右肾动脉血流阻力增高。\\r\\n双肾结构及左肾动脉、双侧肾上腺区未见异常。\", \"报告时间\": \"2022-07-08 18:06:19\", \"检查内容\": \"左肾约112m×49mm×50mm，右肾约121mm×56mm×53mm。\\r\\n双肾大小形态正常，包膜光滑，肾实质与肾窦未见异常回声。\\r\\nCDFI：双肾血管分布正常。\\r\\n因盆腹腔包块