.000000\"}, {\"医嘱id\": \"97881064\", \"申请时间\": \"2022-07-08 09:22:42 至 1-01-01 00:00:00\", \"给药途径\": \"xxx\", \"项目名称\": \"结账出院\", \"医嘱项类别\": \"999\", \"医嘱项规格\": \"xxx\", \"单次剂量数量\": \"0.000000\"}, {\"医嘱id\": \"97881065\", \"申请时间\": \"2022-07-08 09:22:00 至 1-01-01 00:00:00\", \"给药途径\": \"xxx\", \"项目名称\": \"静脉血栓风险评估\", \"医嘱项类别\": \"F00000093284\", \"医嘱项规格\": \"xxx\", \"单次剂量数量\": \"0.000000\"}], \"诊断\": [{\"ICD10名称\": \"子宫粘膜下平滑肌瘤\", \"ICD10编码\": \"D25.000x001\", \"诊断名称\": \"子宫粘膜下平滑肌瘤\", \"诊断时间\": \"2022-07-01 17:23:40\", \"诊断类型\": \"出院主要诊断\", \"诊断编号\": \"ZY010000473047_1_2\", \"住院流水号\": \"ZY010000473047\", \"院内诊断编码\": \"D25.000x001\"}, {\"ICD10名称\": \"中度贫血\", \"ICD10编码\": \"D64.902\", \"诊断名称\": \"中度贫血\", \"诊断时间\": \"2022-07-12 21:43:39\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000473047_2_1\", \"住院流水号\": \"ZY010000473047\", \"院内诊断编码\": \"D64.902\"}, {\"ICD10名称\": \"异常子宫出血\", \"ICD10编码\": \"N93.901\", \"诊断名称\": \"异常子宫出血\", \"诊断时间\": \"2022-07-12 21:43:39\", \"诊断类型\": \"门诊诊断\", \"诊断编号\": \"ZY010000473047_3_1\", \"住院流水号\": \"ZY010000473047\", \"院内诊断编码\": \"N93.901\"}, {\"ICD10名称\": \"异常子宫出血\", \"ICD10编码\": \"N93.901\", \"诊断名称\": \"异常子宫出血\", \"诊断时间\": \"2022-07-12 21:43:39\", \"诊断类型\": \"入院诊断\", \"诊断编号\": \"ZY010000473047_4_1\", \"住院流水号\": \"ZY010000473047\", \"院内诊断编码\": \"N93.901\"}, {\"ICD10名称\": \"平滑肌瘤\", \"ICD10编码\": \"M88900/0\", \"诊断名称\": \"平滑肌瘤\", \"诊断时间\": \"2022-07-12 21:43:39\", \"诊断类型\": \"病理诊断\", \"诊断编号\": \"ZY010000473047_5_2\", \"住院流水号\": \"ZY010000473047\", \"院内诊断编码\": \"M88900/0\"}], \"入院记录\": {\"主诉\": \"经量增多8+月，发现宫腔赘生物1+月。\", \"TNM分期\": \"文本中未提及该内容\", \"个人史\": \"生于出生地，久居本地，无疫水、疫源接触史，无工业毒物、粉尘、放射线物质、化学性物质接触史，无嗜酒史，无吸烟史，否认麻醉毒品等嗜好，否认冶游史，否认性病史。\", \"婚育史\": \"适龄结婚，爱人体健，家庭关系和睦。4-0-2-4，均为足月顺产，1男4女，均体健。曾因早孕行人流2次。\", \"家族史\": \"否认家族性遗传病史、传染病史、肿瘤病史、精神病史。\", \"既往史\": \"既往体健，无肝炎史，无结核史等传染病史，无高血压史，无冠心病史，无糖尿病史等病史，手术史：无手术史，无外伤史，输血史：无输血史，预防免疫史：预防接种史不详，过敏史：无药物、食物过敏史。\", \"月经史\": \"月经初潮14岁，平素月经规则，经期6-7天，周期28-30天，量中（约夜用卫生巾1包，每张打湿1/2），无血块、痛经。2021年11月开始出现经量增多（约夜用卫生巾3包，每张打湿1/2），周期及经量无明显改变。末次月经：2022-06-19，上次月经2022-05-13。\", \"现病史\": \"患者平素月经规则，经期6-7天，周期28-30天，量中（约夜用卫生巾1包，每张打湿1/2），无血块、痛经。2021年11月开始出现经量增多（约夜用卫生巾3包，每张打湿1/2），周期及经量无明显改变。2021-12-31就诊于当地医院行血常规示：HGB58g/L，建议住院治疗，患者因个人因素拒绝，未予重视。2022-05-24患者因头晕，伴有乏力，活动后心悸、胸闷不适，就诊于临高县人民医院，行妇科彩超示：宫颈管处低回声（大小约22mmX6mm）。建议住院治疗，患者拒绝，要求前往上级医院进一步诊治。现就诊我科门诊，行经阴道彩超示：子宫内膜厚4mm，子宫、双侧卵巢未见明显异常；血常规：HGB：51g/L。妇检：宫颈口可见约3cmX3cm的肌瘤样赘生物，门诊医师建议住院治疗。遂以“异常子宫出血：宫腔占位性质待查？”收入院。现患者头晕，伴有乏力，活动后心悸、胸闷，无头痛，无畏寒、发热，无咳嗽、咳痰，无胸闷、气促，无腹胀、腹痛，无肛门坠胀感等不适，近期患者精神状态良好，食欲良好，睡眠良好，大便正常，小便正常，体重无明显变化。\", \"FIGO分期\": \"文本中未提及该内容\", \"专科情况\": \"文本中未提及该内容\", \"体格检查\": \"生命体征：T：36.2℃，P：92次/分，R：20次/分，BP：115/57mmHg。一般情况：发育正常，营养良好，表情自如，自主体位，神志清楚，查体合作。皮肤黏膜：全身皮肤无黄染、出血点、瘀点瘀斑、肝掌、蜘蛛痣。淋巴结：周身浅表淋巴结未触及。头颅五官：头颅大小正常，眼睑无浮肿，结膜无苍白、充血、水肿、出血、结膜下出血，巩膜无黄染，双侧瞳孔等大等圆，对光反射灵敏。耳廓无畸形，外耳道无异常分泌物，无乳突压痛，听力粗测正常。鼻无畸形，无鼻翼煽动，鼻旁窦未触及明显压痛。口唇红润，口腔黏膜未见明显异常，舌未见明显异常，齿龈无出血。齿列整齐，咽部粘膜未见明显异常，声音正常，双侧扁桃体无肿大、无充血、表面无分泌物。颈部：颈两侧对称，颈部无抵抗，气管居中，颈静脉无怒张，肝颈静脉回流征阴性，颈动脉双侧搏动正常，甲状腺不大，无压痛，震颤未触及，未闻及血管杂音。胸部：胸廓无畸形，双侧对称，呼吸动度双侧一致，乳房未见明显异常。肺部：胸部无压痛，语颤双侧均等，胸膜摩擦感未触及，未触及皮下捻发感。双肺叩诊清音，肺肝浊音界位于右侧锁骨中线第五肋间。双肺听诊，呼吸音清晰、无啰音，无胸膜摩擦音。心脏：心前区无隆起，心尖搏动不明显，震颤未触及，无心包摩擦感，心界不大，心率92次/分，心律整齐，未闻及杂音，无心包摩擦音。周围血管征：无。腹部：腹部平坦，未见腹壁静脉曲张，未见胃肠型及蠕动波。腹肌柔软，腹部包块未触及，腹部无压痛，肝脾肋下未触及，Murphy征阴性，无明显肾区叩击痛，腹部叩鼓音，移动性浊音阴性，肠鸣音正常，未闻及高调肠鸣气过水声。肛门直肠、生殖器：肛门、直肠未见明显异常，余详见专科检查。脊柱四肢：脊柱四肢无畸形，活动无障碍，双下肢无指凹性水肿。神经系统：生理反射存在，病理反射未引出。妇 科 检查：外阴：发育正常，阴毛呈女性分布，已婚已产型；阴道：通畅，壁光滑，内见少许白色分泌物，无异味；宫颈：肥大，光滑，宫颈口可见一大小约3cm×3cm肌瘤样赘生物，蒂部位于宫颈管内，直径约1.5cm，触血（+），无举痛；子宫：前位，正常大小，质中，活动可，无压痛；附件：双侧附件区未触及包块，无压痛。\", \"创建时间\": \"2022-07-01 17:12:15\", \"初步诊断\": \"异常子宫出血：宫腔占位性质待查？\", \"更正诊断\": \"文本中未提及该内容\", \"辅助检查\": \"2022-05-30我院经阴道彩超示：子宫内膜厚4mm，子宫、双侧卵巢未见明显异常；2022-05-30血常规：HGB：51g/L。\", \"其他肿瘤分期\": \"文本中未提及该内容\", \"患者一般情况\": \"发育正常，营养良好，表情自如，自主体位，神志清楚，查体合作。\", \"主治医师48小时诊断\": \"文本中未提及该内容\"}, \"出院记录\": {\"合并症\": \"重度贫血\", \"入院情况\": \"入院主诉：经量增多8+月，发现宫腔赘生物1+月。\\n妇检：外阴、阴道（-）；宫颈：肥大，光滑，宫颈口可见一大小约3cm×3cm肌瘤样赘生物，蒂部位于宫颈管内，直径约1.5cm，触血（+），无举痛；子宫：前位，正常大小，质中，活动可，无压痛；附件：双侧附件区未触及包块，无压痛。\", \"入院日期\": \"2022-07-01\", \"入院诊断\": \"经量增多8+月，发现宫腔赘生物1+月。\", \"出院医嘱\": \"1、注意休息，加强营养，院外继续纠正贫血治疗；2、禁性生活、盆浴一个月；3、一个月后门诊复查；4、不适请随诊。\", \"出院情况\": \"现患者一般情况良好，进食、睡眠可，无畏寒、发热，无腹痛、腹胀等不适。\", \"出院日期\": \"2022-07-08\", \"出院诊断\": \"异常子宫出血：宫腔占位性质待查？\", \"创建时间\": \"2022-07-08 15:43:43\", \"治疗结果\": \"术后病理回报示：1.（宫腔内容物）分泌期宫内膜 2.（宫腔管赘生物）粘膜下平滑肌瘤。现患者一般情况良好，进食、睡眠可，无畏寒、发热，无腹痛、腹胀等不适。\", \"诊疗经过\": \"2022-05-30我院经阴道彩超示：子宫内膜厚4mm，子宫、双侧卵巢未见明显异常；2022-05-30血常规：HGB：51g/L↓、红细胞压积 16.7%↓、血小板计数 253×10^9/L；传染病筛查、白带常规、肿瘤六项、甲功三项、粪便常规、生化全套、凝血四项未见明显异常。2022-07-01 血常规:血红蛋白 47g/L↓、红细胞压积 16.7%↓、血小板计数 253×10^9/L；2022-07-02 磁共振盆腔平扫（子宫及附件/膀胱）：宫颈腔内异常信号，考虑偏良性病变可能性大（肌瘤？息肉？）。经阴道超声：子宫腔内多发实性结节，考虑内膜多发息肉；宫颈管实性结节，考虑宫颈管息肉 。双侧卵巢未见明显异常。患者重度贫血，予分次共输注4u同型红悬纠正贫血，2022-07-15复查血常规:血红蛋白 82g/L。与患者沟通，告知患者超声示子宫腔内多发实性结节，大小约7mm×3mm,考虑内膜多发息肉；宫颈管实性结节，大小约25mm×19mm×16mm,考虑宫颈管息肉；双侧卵巢未见明显异常。有手术指征，拟行手术治疗，手术方式为：1.分段诊刮术：费用低，操作相对简单，但存在漏诊可能；2.宫腔镜检术+诊刮术：宫腔镜可明确宫腔内病变及位置，减少漏诊风险。将上述两种手术方式向患者及家属交代清楚，患者及家属要求行宫腔镜检术+诊刮术（备电切）。无明显手术禁忌症，于2022年07月07日送手术室在全麻下行宫腔镜检术+宫腔组织物吸引术+宫颈管赘生物摘除术。术中见：术前探子宫前位，宫腔深约9厘米。宫颈口可见一大小约3cm×3cm息肉样赘生物，蒂部位于宫颈管内，直径约1.5cm，触血（+），子宫内膜均匀增厚。双侧输卵管开口可见，宫颈管未见异常。手术经过顺利，术后安返病房。术后病理回报示：1.（宫腔内容物）分泌期宫内膜 2.（宫腔管赘生物）粘膜下平滑肌瘤。\", \"术后病理pTNM分期\": \"文本中未提及该内容\"}, \"医保信息\": [{\"年龄\": \"42\", \"性别\": \"女性\", \"医疗保险类别代码\": \"xxx\", \"医疗保险类别名称\": \"xxx\"}], \"基本信息\": {\"入院日期\": \"2022-07-01 16:03:29\", \"出院日期\": \"2022-07-08 10:44:38\", \"住院流水号\": \"ZY010000473047\"}, \"手术记录\": [{\"创建时间\": \"xxx\", \"手术名称\": \"宫腔镜检术+宫腔组织物吸引术+宫颈管赘生物摘除术\", \"手术日期\": \"文本中未提及该内容\", \"手术时间\": \"2022年07月07日,11时00分-11时10分\", \"手术经过\": \"1.麻醉成功后，常规消毒铺巾。2.探宫腔深度、扩宫、置入宫腔镜，所见如前述。3.扩宫至7.5号。4.摘取宫颈管赘生物，诊刮内膜,送病理检查。5.探查无异常，退出宫腔镜，结束手术。\", \"术中出血\": \"500ml\", \"术中情况\": \"文本中未提及该内容\", \"术中诊断\": \"文本中未提及该内容\", \"术前诊断\": \"1、异常子宫出血：宫腔占位性质待查？2、轻度贫血\", \"术后诊断\": \"1、宫颈管息肉2、轻度贫血\", \"病灶描述\": \"术前探子宫前位，宫腔深约9厘米。宫颈口可见一大小约3cm×3cm息肉样赘生物，蒂部位于宫颈管内，直径约1.5cm，触血（+），子宫内膜均匀增厚。双侧输卵管开口可见，宫颈管未见异常。\", \"费用相关\": \"治疗类-手术治疗费3820.500000元；治疗类-手术治疗费-麻醉费535.000000元；治疗类-手术治疗费-手术费3285.500000元\", \"住院流水号\": \"ZY010000473047\"}], \"护理记录\": [{\"内容\": \"xxx\", \"时间\": \"xxx\", 