 \"出院\", \"医嘱项类别\": \"999\", \"医嘱项规格\": \"xxx\", \"单次剂量数量\": \"0.000000\"}], \"诊断\": [{\"ICD10名称\": \"梗阻性黄疸\", \"ICD10编码\": \"K83.109\", \"诊断名称\": \"梗阻性黄疸\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"出院主要诊断\", \"诊断编号\": \"ZY010000519914_1_2\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"K83.109\"}, {\"ICD10名称\": \"急性胰腺炎\", \"ICD10编码\": \"K85.900\", \"诊断名称\": \"急性胰腺炎\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000519914_2_2\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"K85.900\"}, {\"ICD10名称\": \"肝功能不全\", \"ICD10编码\": \"K72.905\", \"诊断名称\": \"肝功能不全\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000519914_3_1\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"K72.905\"}, {\"ICD10名称\": \"频发性房性期前收缩\", \"ICD10编码\": \"I49.100x002\", \"诊断名称\": \"频发性房性期前收缩\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000519914_4_2\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"I49.100x002\"}, {\"ICD10名称\": \"胰腺占位性病变\", \"ICD10编码\": \"R93.302\", \"诊断名称\": \"胰腺占位性病变\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000519914_5_2\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"R93.302\"}, {\"ICD10名称\": \"钾缺乏\", \"ICD10编码\": \"E87.600x003\", \"诊断名称\": \"钾缺乏\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000519914_6_2\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"E87.600x003\"}, {\"ICD10名称\": \"低蛋白血症\", \"ICD10编码\": \"E77.801\", \"诊断名称\": \"低蛋白血症\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"其他诊断\", \"诊断编号\": \"ZY010000519914_7_1\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"E77.801\"}, {\"ICD10名称\": \"梗阻性黄疸\", \"ICD10编码\": \"K83.109\", \"诊断名称\": \"梗阻性黄疸\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"门诊诊断\", \"诊断编号\": \"ZY010000519914_8_1\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"K83.109\"}, {\"ICD10名称\": \"梗阻性黄疸\", \"ICD10编码\": \"K83.109\", \"诊断名称\": \"梗阻性黄疸\", \"诊断时间\": \"2023-12-19 08:54:59\", \"诊断类型\": \"入院诊断\", \"诊断编号\": \"ZY010000519914_9_1\", \"住院流水号\": \"ZY010000519914\", \"院内诊断编码\": \"K83.109\"}], \"入院记录\": {\"主诉\": \"腹痛伴反酸、皮肤黄染2周。\", \"TNM分期\": \"文本中未提及该内容\", \"个人史\": \"生于出生地，久居本地，无疫水、疫源接触史，无工业毒物、粉尘、放射线物质接触史，无嗜酒史，无吸烟史，否认麻醉毒品等嗜好，否认冶游史，否认性病史。\", \"婚育史\": \"适龄结婚，育有1男3女，家人均体健。\", \"家族史\": \"患者配偶及子女无患有同样疾病者，否认家族性遗传病史，否认传染病史，无肿瘤病史。\", \"既往史\": \"‘右侧腹股沟疝’术后病史，具体术式不详；无肝炎史，无结核史等传染病史，无高血压史，无冠心病史，无糖尿病史等病史，手术史：无手术史，无外伤史，输血史：无输血史，预防免疫史：预防接种史不详，过敏史：无药物、食物过敏史。\", \"月经史\": \"月经初潮14岁，5-7/28-30,既往月经规律，月经量适中，无痛经。已绝经。\", \"现病史\": \"患者于2周前无明显诱因后出现上腹部腹痛，为持续性绞痛，阵发加剧，休息后未见明显缓解，伴反酸,逐渐出现全身皮肤黄染及瘙痒，无发热、寒战，无心慌、心悸，无呼吸困难，就诊昌江黎族自治县中西医结合医院，诊断“腹痛、黄疸待查：急性胰腺炎？”予对症治疗后未见明显缓解，今为进一步治疗，就诊我院门诊，门诊拟“腹痛查因：急性胰腺炎？”收入我科。\", \"FIGO分期\": \"文本中未提及该内容\", \"专科情况\": \"腹部膨隆，右腹股沟区可见一长约5cm陈旧手术瘢痕，未见腹壁静脉曲张，未见胃肠型及蠕动波。腹部压痛，以脐周为主，腹肌柔软，肝脾肋下未触及，Murphy征阴性，无明显肾区叩击痛，腹部包块未触及，腹部叩鼓音，移动性浊音阴性，肠鸣音稍弱，未闻及高调肠鸣气过水声。\", \"体格检查\": \"生命体征：T：36.5℃，P：76次/分，R：18次/分，BP：153/88mmHg。一般情况：发育正常，营养肥胖，痛苦面容，表情自如，自主体位，步态正常，神志清楚，查体合作。皮肤黏膜：全身皮肤有黄染，无出血点、瘀点瘀斑、肝掌、蜘蛛痣。淋巴结：周身浅表淋巴结未触及。头颅五官：头颅大小正常，右眼失明，眼睑无浮肿，结膜无苍白、充血、水肿、出血、结膜下出血，巩膜有黄染，双侧瞳孔等大等圆，对光反射灵敏。耳廓无畸形，外耳道无异常分泌物，无乳突压痛，听力粗测正常。鼻无畸形，无鼻翼煽动，鼻旁窦未触及明显压痛。口唇红润，口腔黏膜未见明显异常，舌未见明显异常，齿龈无出血。齿列整齐，咽部粘膜未见明显异常，声音正常，双侧扁桃体无肿大、无充血、表面无分泌物。颈部：颈两侧对称，颈部无抵抗，气管居中，颈静脉无怒张，肝颈静脉回流征阴性，颈动脉双侧搏动正常，甲状腺不大，无压痛，震颤未触及，未闻及血管杂音。胸部：胸廓无畸形，双侧对称，呼吸动度双侧一致，乳房未见明显异常。肺部：胸部无压痛，语颤双侧均等，胸膜摩擦感未触及，未触及皮下捻发感。双肺叩诊清音，肺肝浊音界位于右侧锁骨中线第5肋间。双肺听诊，呼吸音清晰、无啰音，无胸膜摩擦音。心脏：心前区无隆起，心尖搏动不明显，震颤未触及，无心包摩擦感，心界不大，心率76次/分，心律整齐，未闻及杂音，无心包摩擦音。周围血管征：无。腹部：详见外科情况。肛门直肠、生殖器：外生殖器、肛门、直肠未见明显异常。脊柱四肢：脊柱四肢无畸形，活动无障碍，双下肢无指凹性水肿。神经系统：双侧肱二、三头肌反射正常，双侧膝腱反射正常，双侧跟腱反射正常，双侧Kernig征阴性，Babinski征阴性，Oppenheim征阴性，Hoffmann征阴性，Brudzinski征阴性。专科情况：腹部膨隆，右腹股沟区可见一长约5cm陈旧手术瘢痕，未见腹壁静脉曲张，未见胃肠型及蠕动波。腹部压痛，以脐周为主，腹肌柔软，肝脾肋下未触及，Murphy征阴性，无明显肾区叩击痛，腹部包块未触及，腹部叩鼓音，移动性浊音阴性，肠鸣音稍弱，未闻及高调肠鸣气过水声。\", \"创建时间\": \"2023-12-01 16:06:37\", \"初步诊断\": \"梗阻性黄疸:胆道肿瘤？结石？\\n梗阻性黄疸:胆道肿瘤？结石？\\n急性胰腺炎\\n肝功能不全\", \"更正诊断\": \"文本中未提及该内容\", \"辅助检查\": \"2023-11-27腹部增强CT检查提示：1.考虑急性胰腺炎，2.胆总管及肝内胆管稍扩张。\", \"其他肿瘤分期\": \"文本中未提及该内容\", \"患者一般情况\": \"发育正常，营养肥胖，痛苦面容，表情自如，自主体位，步态正常，神志清楚，查体合作。\", \"主治医师48小时诊断\": \"文本中未提及该内容\"}, \"出院记录\": {\"合并症\": \"右侧腹股沟疝术后\", \"入院情况\": \"患者***，女，82岁。主因腹痛伴反酸、黄染2周余入院。患者于2周前无明显诱因后出现腹痛症状，为持续性绞痛，阵发加剧，伴反酸、全身皮肤黄染。既往“右侧腹股沟疝术后”病史，具体术式不详。\", \"入院日期\": \"2023-11-30\", \"入院诊断\": \"腹痛伴反酸、黄染2周余。\", \"出院医嘱\": \"1、注意休息，避免劳累；\\n2、院外继续治疗；定期检测血常规、血生化等相关指标；\\n3、如有不适，门诊随诊。\", \"出院情况\": \"患者无恶心、呕吐，无发热、畏寒等不适。查体：腹部平软，上腹部腹部轻压痛，肝脾肋下未触及，Murphy征阴性，无明显肾区叩击痛，腹部包块未触及，腹部叩鼓音，移动性浊音阴性，肠鸣音正常。\", \"出院日期\": \"2023-12-18\", \"出院诊断\": \"梗阻性黄疸:胆道肿瘤？结石？\", \"创建时间\": \"2023-12-17 08:33:28\", \"治疗结果\": \"患者目前一般情况可。\", \"诊疗经过\": \"入院完善辅助检查，2023-12-01 凝血四项:凝血酶原时间 13.3s↑、纤维蛋白原定量 3.97g/L↑；2023-12-01 肾功能检测/淀粉酶测定/电解质全项./蛋白检测/心肌酶全项/血糖(GLU)./血脂全项/肝功能酶检测:丙氨酸氨基转移酶 221U/L↑、天冬氨酸氨基转移酶 236U/L↑、钾 3.17mmol/L↓、白蛋白 29.2g/L↓、总胆固醇 5.95mmol/L↑；2023-11-30 常规心电图检查(组套),1.窦性心律，2.频发房性早搏  房早未下传，3.一度房室阻滞，4.T波改变；2023-12-02 [螺旋CT胰腺三维成像(组套)(第一部位)][螺旋CT上腹部增强(组套)(第一部位)],1、胰头部占位,考虑胰头占位,继发急性胰腺炎,并脾静脉癌栓形成,建议MR平扫及增强检查。2、胆总管下段狭窄,炎性改变与肿瘤鉴别,建议复查。3、肝硬化。4、肝脏散在多发囊肿;肝脏散在钙化灶。5、范围内,左肾囊肿。右膈胸膜钙化。2023-12-02 [磁共振MRCP(胰胆管水成像)],1.MRCP检查示胆总管下段梗阻,继发肝内外胆管和胰管扩张,建议结合CT/MRI增强检查。2.范围内:肝内多发小囊肿;考虑胰腺炎;可疑胰头占位;左肾囊肿。完善术前准备，于2023年12月06日行内镜逆行胰胆管造影（ERCP）+EST+金属支架置入术，术后予预防感染、护胃、护肝及补液等对症支持治疗。\", \"术后病理pTNM分期\": \"文本中未提及该内容\"}, \"医保信息\": [{\"年龄\": \"82\", \"性别\": \"女性\", \"医疗保险类别代码\": \"xxx\", \"医疗保险类别名称\": \"xxx\"}], \"基本信息\": {\"入院日期\": \"2023-11-30 16:45:54\", \"出院日期\": \"2023-12-18 08:47:08\", \"住院流水号\": \"ZY010000519914\"}, \"手术记录\": [{\"创建时间\": \"xxx\", \"手术名称\": \"内镜逆行胰胆管造影（ERCP）+EST+金属支架置入术\", \"手术日期\": \"文本中未提及该内容\", \"手术时间\": \"2023年12月06日\", \"手术经过\": \"麻醉起效后，患者侧卧位，十二指肠镜顺利进入十二指肠降段，可见乳头外观轻度肿胀，开口呈绒毛状。胆总管插管困难，以波科一次性括约肌切开刀带导丝（库克）多次插管未成功，采用一个奥林巴斯高频乳头切开刀（针状刀，KD-V451M）予乳头粘膜下预切开后，换用泥鳅导丝再次胆管插管成功，注入25%欧乃派克20ml，X线透视下，胆总管下段明显狭窄，狭窄段长约3cm，胆总管狭窄段以上扩张，直径约1.1cm，肝内胆管扩张，顺导丝(库克)置入一根长度为6cm，直径为10mm的覆膜胆道金属支架（南京微创），支架近端位于狭窄段上缘2cm，远端距乳头约1cm，支架固定好，可见墨色胆汁流出。手术顺利，术中术后无特殊不适，安返病房。\", \"术中出血\": \"无\", \"术中情况\": \"文本中未提及该内容\", \"术中诊断\": \"文本中未提及该内容\", \"术前诊断\": \"梗阻性黄疸:胆道肿瘤？结石？ 急性胰腺炎 肝功能不全\", \"术后诊断\": \"梗阻性黄疸:胆道肿瘤？结石？ 急性胰腺炎 肝功能不全\", \"病灶描述\": \"患者侧卧位，十二指肠镜顺利进入十二指