: \"3.270000\", \"ORDER_ITEM_CODE\": \"5973\", \"收费项目代码\": \"5973\", \"收费项目名称\": \"(合)盐酸阿罗洛尔片\"}, {\"ORDER_NO\": \"115394779\", \"住院号\": \"ZY050000404417\", \"收费日期\": \"2023-10-19 09:28:28\", \"项目单价\": \"3.180000\", \"项目单位\": \"片\", \"项目数量\": \"1.000000\", \"项目费用\": \"3.180000\", \"ORDER_ITEM_CODE\": \"Y00000011988\", \"收费项目代码\": \"Y00000011988\", \"收费项目名称\": \"(合)沙库巴曲缬沙坦钠片\"}, {\"ORDER_NO\": \"115394778\", \"住院号\": \"ZY050000404417\", \"收费日期\": \"2023-10-20 09:29:52\", \"项目单价\": \"3.270000\", \"项目单位\": \"片\", \"项目数量\": \"1.000000\", \"项目费用\": \"3.270000\", \"ORDER_ITEM_CODE\": \"5973\", \"收费项目代码\": \"5973\", \"收费项目名称\": \"(合)盐酸阿罗洛尔片\"}, {\"ORDER_NO\": \"115394779\", \"住院号\": \"ZY050000404417\", \"收费日期\": \"2023-10-20 09:29:52\", \"项目单价\": \"3.180000\", \"项目单位\": \"片\", \"项目数量\": \"1.000000\", \"项目费用\": \"3.180000\", \"ORDER_ITEM_CODE\": \"Y00000011988\", \"收费项目代码\": \"Y00000011988\", \"收费项目名称\": \"(合)沙库巴曲缬沙坦钠片\"}, {\"ORDER_NO\": \"115973336\", \"住院号\": \"ZY050000404417\", \"收费日期\": \"2023-10-20 15:27:05\", \"项目单价\": \"2.920000\", \"项目单位\": \"袋\", \"项目数量\": \"9.000000\", \"项目费用\": \"26.240000\", \"ORDER_ITEM_CODE\": \"Y00000011656\", \"收费项目代码\": \"Y00000011656\", \"收费项目名称\": \"稳心颗粒（无蔗糖）\"}], \"检查报告\": [{\"检查ID\": \"xxx\", \"图像分析\": \"1.双肺散在少许慢性炎症及纤维灶，较前部分吸收，请结合临床随诊。\\r\\n2.双肺散在小结节，考虑炎性结节，建议随诊复查（12个月）。\\r\\n3.心包稍增厚；主动脉硬化。\\r\\n4.胸骨后甲状腺肿可能性大，气管受压推移，同前，建议超声检查。\\r\\n5.右侧胸膜稍增厚。\\r\\n6.双侧基底节区及放射冠腔隙性梗死灶，建议必要时MR进一步检查。\", \"报告时间\": \"2023-09-27 10:48:53\", \"检查内容\": \"对比2023-04-02CT胸部平扫，现片示：\\r\\n    双肺纹理清晰，双肺散在少许条索状高密度影，较前部分吸收；双肺见散在小结节影，大者在左肺下叶前内基底段（6-43），直径约4mm，边界清。气管及主要支气管通畅。双侧肺门及纵隔未见增大淋巴结。心脏不大，心包稍增厚。主动脉管壁可见钙化影。双侧胸腔未见积液。右侧胸膜稍增厚。扫及骨质未见明确异常。\\r\\n    甲状腺右叶及峡部不规则增大，密度不均匀，内见条状致密影，并部分凸入上纵隔，同前，气管向左侧偏移。\\r\\n    双侧大脑及小脑半球对称，双侧基底节区及放射冠可见少许点片状低密度灶，边界模糊，无明显占位效应，余脑实质未见明显异常密度影。脑室不大。脑池、脑沟、脑裂无增宽。中线结构居中。颅骨未见异常。\", \"检查描述\": \"xxx\", \"检查时间\": \"2023-09-26 16:49:04\", \"检查部位\": \"[螺旋CT胸部平扫(组套)(第一部位)][螺旋CT颅脑三维成像(组套)(第一部位)]\", \"检查项目\": \"计算机X线断层摄影（CT）\", \"申请时间\": \"2023-09-26 16:30:00\", \"住院流水号\": \"ZY050000404417\", \"检查子类型\": \"[螺旋CT胸部平扫(组套)(第一部位)][螺旋CT颅脑三维成像(组套)(第一部位)]\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"xxx\", \"报告时间\": \"2023-09-26 16:55:14\", \"检查内容\": \"xxx\", \"检查描述\": \"xxx\", \"检查时间\": \"2023-09-26 15:30:00\", \"检查部位\": \"[左心功能测定(舒张加收)]\", \"检查项目\": \"超声检查\", \"申请时间\": \"2023-09-26 15:30:00\", \"住院流水号\": \"ZY050000404417\", \"检查子类型\": \"[左心功能测定(舒张加收)]\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"左室舒张功能减退；左室收缩功能测值正常。\\r\\n二尖瓣、三尖瓣轻度反流。\", \"报告时间\": \"2023-09-26 16:57:48\", \"检查内容\": \"超声测值（单位mm）：\\r\\n主动脉窦部AO33，肺动脉PA19，左心房LA前后径34、左右径35，右心房RA32，\\r\\n左室舒张径LVD45，左室收缩径LVS27，右室RVD24，室间隔IVST10，左室后壁LVPWT8。\\r\\n瓣口流速（m/s）：\\r\\nMV E0.71，MV A0.82，TV E0.49，TV A0.39，AV1.18，PV0.87。\\r\\n左心功能测定：EDV94ml；ESV28ml；SV67ml；射血分数EF71%；左室缩短率FS40％；\\r\\nMV E/A＜1；Ea5.5/Aa9.8<1。\\r\\n2Ｄ及Ｍ型特征：\\r\\n各房室腔测值正常。房、室间隔连续完整。室壁厚度测值正常，运动协调，收缩幅度正常。各瓣膜形态、结构、启闭运动未见明显改变。大动脉关系、内径正常。心包腔未见分离性液性区。\\r\\nCDFI及PW/CW/TDI特征：\\r\\n二尖瓣见少量反流。\\r\\n三尖瓣见少量反流，反流速度2.4m/s，估算肺动脉收缩压2.4mmHg。\", \"检查描述\": \"xxx\", \"检查时间\": \"2023-09-26 15:55:04\", \"检查部位\": \"[心脏超声(组套)] [左心功能测定(舒张加收)] [左心功能测定]\", \"检查项目\": \"超声检查\", \"申请时间\": \"2023-09-26 15:30:00\", \"住院流水号\": \"ZY050000404417\", \"检查子类型\": \"[心脏超声(组套)] [左心功能测定(舒张加收)] [左心功能测定]\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"xxx\", \"报告时间\": \"2023-09-26 16:55:05\", \"检查内容\": \"xxx\", \"检查描述\": \"xxx\", \"检查时间\": \"2023-09-26 15:30:00\", \"检查部位\": \"[左心功能测定]\", \"检查项目\": \"超声检查\", \"申请时间\": \"2023-09-26 15:30:00\", \"住院流水号\": \"ZY050000404417\", \"检查子类型\": \"[左心功能测定]\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"甲状腺多发结节，符合（中国版） TI-RADS 3 类。\", \"报告时间\": \"2023-09-28 08:33:18\", \"检查内容\": \"甲状腺形态失常，左、右叶厚度分别约9.9mm和24.8mm，峡部厚约3.4mm。腺体包膜光滑。\\r\\n甲状腺右叶内见多个局部异常回声区，大者最大切面呈不规则形稍低回声，A<T，最大切面大小约23.3mm×20.2mm，边界模糊，内部回声不均匀，内见少量液体无回声区，内另见1个后方伴声影的较大片状强回声，整体后方回声未见明显改变，CDFI显示内见少量彩流信号；其余者无特殊。\\r\\n其余腺实质呈均匀等回声，CDFI见少量血流信号。\\r\\n双侧颈部未见增大淋巴结或形态异常淋巴结回声。\", \"检查描述\": \"xxx\", \"检查时间\": \"2023-09-28 08:33:17\", \"检查部位\": \"[(浅表)甲状腺(彩超)]\", \"检查项目\": \"超声检查\", \"申请时间\": \"2023-09-28 08:15:00\", \"住院流水号\": \"ZY050000404417\", \"检查子类型\": \"[(浅表)甲状腺(彩超)]\"}, {\"检查ID\": \"xxx\", \"图像分析\": \"1.肝右后叶下段囊肿。\\r\\n2.右肾下极血管平滑肌脂肪瘤。\\r\\n3.范围内：右肺中叶内侧段及左肺上叶下舌段少许纤维灶。\", \"报告时间\": \"2023-09-29 09:53:32\", \"检查内容\": \"肝:形态、大小、各叶比例未见明确异常。肝实质密度均匀。肝右后叶下段见类圆形囊性密度影，边界清，直径约15mm。\\r\\n    胆管：肝内外胆管未见明显扩张。\\r\\n    胆囊：充盈尚可，形态、大小未见明确异常，胆囊壁未见明显增厚，腔内未见异常密度影。\\r\\n    胰腺：形态大小、密度未见异常，胰周脂肪间隙清晰，胰管未见明显扩张。\\r\\n    脾脏:形态、大小、密度未见明确异常。\\r\\n    双肾及双肾上腺:双肾形态、大小未见明确异常，双侧肾盂、肾盏未见明显扩张积水，右肾下极包膜下见一低密度灶，边界清，直径约22mm，CT值约-81HU。\\r\\n    膀胱:充盈尚可，形态、大小未见明显异常，腔内未见明确异常密度影，膀胱壁未见明显增厚。\\r\\n    子宫及双侧附件区:未见明确异常。\\r\\n    肠曲：分布、形态及密度未见异常。\\r\\n    腹膜后:未见明显增大淋巴结。未见腹水征。\\r\\n    范围内：右肺中叶内侧段及左肺上叶下舌段可见少许条索状高密度影。\", \"检查描述\": \"xxx\", \"检查时间\": \"2023-09-28 14:45:43\", \"检查部位\": \"[螺旋CT平扫(上腹部)(第一部位)][螺旋CT下腹部三维成像(组套)(第二部位)]\", \"检查项目\": \"计算机X线断层摄影（CT）\", \"申请时间\": \"2023-09-28 14:30:00\", \"住院流水号\": \"ZY050000404417\", \"检查子类型\": \"[螺旋CT平扫(上腹部)(第一部位)][螺旋CT下腹部三维成像(组套)(第二部位)]\"}], \"检验报告\": [{\"单位\": \"xxx\", \"检验ID\": \"AVI20230927506\", \"检测值\": \"O型\", \"报告时间\": \"2023-09-27 09:06:10\", \"检验时间\": \"2023-09-27 09:06:10\", \"检验结果\": \"xxx\", \"检验详情\": \"xxx\", \"检验项目\": \"ABO+Rh血型鉴定(仪器法)\", \"申请时间\": \"2023-09-26 11:52:12\", \"住院流水号\": \"ZY050000404417\", \"正常值上限\": \"xxx\", \"正常值下限\": \"xxx\"}, {\"单位\": \"xxx\", \"检验ID\": \"AVI20230927506\", \"检测值\": \"阳性\", \"报告时间\": \"2023-09-27 09:06:10\", \"检验时间\": \"2023-09-27 09:06:10\", \"检验结果\": \"xxx\", \"检验详情\": \"xxx\", \"检验项目\": \"ABO+Rh血型鉴定(仪器法)\", \"申请时间\": \"2023-09-26 11:52:12\", \"住院流水号\": \"ZY050000404417\", \"正常值上限\": \"xxx\", \"正常值下限\": \"xxx\"}, {\"单位\": \"S/CO\", \"检验ID\": \"Alinty2023092720\", \"检测值\": \"0.450\", \"报告时间\": \"2023-09-27 10:08:17\", \"检验时间\": \"2023-09-27 10:08:17\", \"检验结果\": \"0.450S/CO\", \"检验详情\": \"0.450S/CO\", \"检验项目\": \"乙肝五项定量(化学发光法)\", \"申请时间\": \"2023-09-26 11:52:12\", \"住院流水号\": \"ZY050000404417\", \"正常值上限\": \"1.00\", \"正常值下限\": \"0.00\"}, {\"单位\": \"%lnh\", \"检验ID\": \"Alinty2023092720\", \"检测值\": \"2.700\", \"报告时间\": \"2023-09-27 10:08:1