INSERT INTO `rules_rule` VALUES (1,'R-0001','使用艾普拉唑须有十二指肠溃疡、反流性食管炎诊断','',1,'超限定用药','2026-06-17 03:23:40.007603','2026-06-30 10:22:43.620246','def execute_rule(ctx):\n    # Phase 1: Prepare Data\n    med_list = get_val(ctx, \"用药信息\", default=[])\n    target_items = filter_list(med_list, \"药品通用名\", \"艾普拉唑\", \"contains\")\n    \n    diag_list = get_val(ctx, \"诊断信息\", default=[])\n    matched_icd = filter_list(diag_list, \"ICD 编码\", [\"K26\", \"K21\"], \"startswith\")\n    target_keywords = [\"十二指肠溃疡\", \"反流性食管炎\"]\n    matched_names = filter_list(diag_list, \"诊断名称\", target_keywords, \"contains\")\n    \n    admission = get_val(ctx, \"入院记录\", default={})\n    \n    # Phase 2: Predicates\n    is_target = len(target_items) > 0\n    \n    has_hard_evidence = len(matched_icd) > 0 or len(matched_names) > 0\n    \n    has_ai_evidence = False\n    if not has_hard_evidence and is_target:\n        emr_context = \"; \".join([\n            f\"现病史：{get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史：{get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断：{get_val(admission, \'初步诊断\', \'\')}\",\n        ])\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否明确确诊为十二指肠溃疡或反流性食管炎？\",\n            )\n    \n    # Phase 3: Logic & Result\n    compliant = has_hard_evidence or has_ai_evidence\n    fail_msg = \"\"\n    if is_target and not compliant:\n        fail_msg = \"适应症不符：艾普拉唑限十二指肠溃疡或反流性食管炎，未发现相关诊断或病史支持\"\n        \n    # Build Evidence Highlights\n    highlights = []\n    # Highlight target drugs with indices\n    for idx, item in enumerate(target_items):\n        highlights.append({\n            \"field_path\": f\"$.用药信息[{idx}].药品通用名\",\n            \"highlighted_text\": str(get_val(item, \"药品通用名\", \"\"))\n        })\n    # Highlight matched ICDs with indices\n    for idx, item in enumerate(matched_icd):\n        highlights.append({\n            \"field_path\": f\"$.诊断信息[{idx}].ICD 编码\",\n            \"highlighted_text\": str(get_val(item, \"ICD 编码\", \"\"))\n        })\n    # Highlight matched Diagnosis Names with indices\n    for idx, item in enumerate(matched_names):\n        highlights.append({\n            \"field_path\": f\"$.诊断信息[{idx}].诊断名称\",\n            \"highlighted_text\": str(get_val(item, \"诊断名称\", \"\"))\n        })\n        \n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"summary\": {\n                \"matched_drug\": get_val(target_items, \"药品通用名\"),\n                \"icd_evidence\": get_val(matched_icd, \"ICD 编码\"),\n                \"name_evidence\": get_val(matched_names, \"诊断名称\"),\n                \"ai_result\": has_ai_evidence,\n            },\n            \"highlights\": highlights,\n        },\n    )','','','艾普拉唑'),(14,'R-0002','使用醋酸钙须有高磷血症诊断','',1,'超限定用药','2026-06-25 14:18:34.022951','2026-06-29 09:06:13.354009','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"醋酸钙\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n    print(diag_list)\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"E83.300x009\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"高磷血症\"], \"contains\")\n    \n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    \n    if not has_hard_evidence:\n\n        admission = get_val(ctx, \"入院记录\", {})\n\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否明确确诊为\'高磷血症\'？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：醋酸钙限高磷血症患者使用，未发现相关诊断或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),   \n            \"name_evidence\": get_val(matched_names, \"诊断名称\"), \n            \"ai_result\": has_ai_evidence\n        }\n    )','','','醋酸钙'),(16,'R-0003','使用注射用右兰索拉唑须有胃、十二指肠溃疡诊断且存在出血症状','',1,'超限定用药','2026-06-29 09:08:30.012053','2026-06-29 09:08:30.012053','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"注射用右兰索拉唑\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n    \n    diag_list = get_val(ctx, \"诊断信息\")\n\n    ulcer_icds = filter_list(diag_list, \"ICD编码\", [\"K25\", \"K26\", \"K27\"], \"startswith\")\n    ulcer_names = filter_list(diag_list, \"诊断名称\", [\"胃溃疡\", \"十二指肠溃疡\"], \"contains\")\n    \n    has_ulcer = (len(ulcer_icds) > 0) or (len(ulcer_names) > 0)\n\n    bleeding_icds = filter_list(diag_list, \"ICD编码\", [\"K92\"], \"startswith\")\n    bleeding_names = filter_list(diag_list, \"诊断名称\", [\"出血\", \"呕血\", \"黑便\"], \"contains\")\n\n    has_bleeding = (len(bleeding_icds) > 0) or (len(bleeding_names) > 0)\n\n    has_hard_evidence = has_ulcer and has_bleeding\n\n    has_ai_evidence = False\n\n    if not has_hard_evidence:\n        admission = get_val(ctx, \"入院记录\", {})\n        \n        parts = [\n            f\"主诉: {get_val(admission, \'主诉\', \'\')}\",\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            # Explicitly ask for BOTH conditions\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否同时满足以下两个条件：1.确诊为胃溃疡或十二指肠溃疡；2.伴有出血症状（如呕血、黑便或大便潜血阳性）？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        missing = []\n        if not has_ulcer: missing.append(\"胃/十二指肠溃疡\")\n        if not has_bleeding: missing.append(\"出血症状\")\n        fail_msg = f\"适应症不符：注射用右兰索拉唑限出血性溃疡，缺失条件：{\'/\'.join(missing)}\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"ulcer_icd\": get_val(ulcer_icds, \"ICD编码\"),\n            \"ulcer_name\": get_val(ulcer_names, \"诊断名称\"),\n            \"bleeding_icd\": get_val(bleeding_icds, \"ICD编码\"),\n            \"bleeding_name\": get_val(bleeding_names, \"诊断名称\"),\n            \"ai_result\": has_ai_evidence\n        }\n    )','','','注射用右兰索拉唑'),(17,'R-0004','使用奥美拉唑碳酸氢钠干混悬剂(Ⅰ)须有活动性十二指肠溃疡或胃食管反流病诊断','',1,'超限定用药','2026-06-29 09:08:51.684529','2026-06-29 09:08:51.684529','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"奥美拉唑碳酸氢钠干混悬剂\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"K26\", \"K21\"], \"startswith\")\n\n    target_keywords = [\"十二指肠溃疡\", \"胃食管反流\", \"反流性食管炎\"]\n    matched_names = filter_list(diag_list, \"诊断名称\", target_keywords, \"contains\")\n\n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n\n    if not has_hard_evidence:\n        admission = get_val(ctx, \"入院记录\", {})\n        \n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否确诊为\'活动性十二指肠溃疡\'或\'胃食管反流病\'(GERD)？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：奥美拉唑碳酸氢钠限\'活动性十二指肠溃疡\'或\'胃食管反流病\'，未发现相关诊断(K26/K21)或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),\n            \"name_evidence\": get_val(matched_names, \"诊断名称\"),\n            \"ai_result\": has_ai_evidence\n        }\n    )','','','奥美拉唑碳酸氢钠干混悬剂(Ⅰ)'),(18,'R-0005','使用奥美拉唑碳酸氢钠胶囊 (Ⅱ)须有活动性良性胃溃疡诊断','',1,'超限定用药','2026-06-29 09:09:09.595515','2026-06-29 09:09:09.595515','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"奥美拉唑碳酸氢钠\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"K25\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"胃溃疡\"], \"contains\")\n\n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n\n    if not has_hard_evidence:\n        admission = get_val(ctx, \"入院记录\", {})\n        \n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否确诊为\'活动性\'且\'良性\'的胃溃疡？(排除恶性肿瘤及陈旧性溃疡)\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：奥美拉唑碳酸氢钠限\'活动性良性胃溃疡\'，未发现相关诊断(K25)或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),\n            \"name_evidence\": get_val(matched_names, \"诊断名称\"),\n            \"ai_result\": has_ai_evidence\n        }\n    )','','','奥美拉唑碳酸氢钠胶囊 (Ⅱ)'),(19,'R-0006','使用谷胱甘肽须有肝功能异常诊断','',1,'超限定用药','2026-06-29 09:09:29.582619','2026-06-29 09:09:29.582619','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"谷胱甘肽\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n    print(diag_list)\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"R94.5\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"肝功能异常\"], \"contains\")\n    \n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    \n    if not has_hard_evidence:\n\n        admission = get_val(ctx, \"入院记录\", {})\n\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否明确确诊为肝功能异常？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：谷胱甘肽限肝功能异常患者使用，未发现相关诊断或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),   \n            \"name_evidence\": get_val(matched_names, \"诊断名称\"), \n            \"ai_result\": has_ai_evidence\n        }\n    )','','','谷胱甘肽'),(20,'R-0007','使用精氨酸谷氨酸注射液须有肝性脑病诊断','',1,'超限定用药','2026-06-29 09:10:04.840361','2026-06-29 09:10:04.840361','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"精氨酸谷氨酸注射液\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n    print(diag_list)\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"K72.903\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"肝性脑病\"], \"contains\")\n    \n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    \n    if not has_hard_evidence:\n\n        admission = get_val(ctx, \"入院记录\", {})\n\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否明确确诊为\'肝性脑病\'？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：精氨酸谷氨酸注射液限肝性脑病患者使用，未发现相关诊断或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),   \n            \"name_evidence\": get_val(matched_names, \"诊断名称\"), \n            \"ai_result\": has_ai_evidence\n        }\n    )','','','精氨酸谷氨酸注射液'),(21,'R-0008','使用利那洛肽胶囊须有便秘型肠易激综合征(IBS-C)诊断且年龄需大于18','',1,'超限定用药','2026-06-29 09:10:24.290203','2026-06-29 09:10:25.710705','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"利那洛肽\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    raw_ages = get_val(ctx, \"医保信息.年龄\")\n\n    val = raw_ages[0] if raw_ages else None\n    patient_age = float(val) if val is not None else -1\n\n    is_adult = is_compare(patient_age, \">=\", 18)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"K58\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"便秘型肠易激综合征\", \"IBS-C\"], \"contains\")\n\n    has_hard_evidence = (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    if is_adult and not has_hard_evidence:\n        admission = get_val(ctx, \"入院记录\", {})\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否确诊为\'便秘型肠易激综合征\' (IBS-C)？\"\n            )\n\n    compliant = is_adult and (has_hard_evidence or has_ai_evidence)\n    \n    fail_msg = \"\"\n    if not compliant:\n        if not is_adult:\n            fail_msg = f\"年龄限制不符：利那洛肽限成年人(>=18)使用，患者年龄为 {patient_age}\"\n        else:\n            fail_msg = \"适应症不符：未发现\'便秘型肠易激综合征(IBS-C)\'的相关诊断\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"patient_age\": patient_age,\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),\n            \"name_evidence\": get_val(matched_names, \"诊断名称\"),\n            \"ai_result\": has_ai_evidence\n        }\n    )','','','利那洛肽胶囊'),(22,'R-0009','使用艾塞那肽注射液须有2型糖尿病诊断','',1,'超限定用药','2026-06-29 09:10:44.866594','2026-06-29 09:10:47.893411','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"艾塞那肽注射液\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n    print(diag_list)\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"E11\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"2型糖尿病\", \"II型糖尿病\"], \"contains\")\n    \n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    \n    if not has_hard_evidence:\n\n        admission = get_val(ctx, \"入院记录\", {})\n\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否明确确诊为\'2型糖尿病\'？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：艾塞那肽限2型糖尿病患者使用，未发现相关诊断或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),   \n            \"name_evidence\": get_val(matched_names, \"诊断名称\"), \n            \"ai_result\": has_ai_evidence\n        }\n    )','','','艾塞那肽注射液'),(23,'R-0010','使用利拉鲁肽注射液须有2型糖尿病诊断','',1,'超限定用药','2026-06-29 09:11:03.475777','2026-06-29 09:11:40.695711','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"利拉鲁肽注射液\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n    print(diag_list)\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"E11\"], \"startswith\")\n\n    matched_names = filter_list(diag_list, \"诊断名称\", [\"2型糖尿病\", \"II型糖尿病\"], \"contains\")\n    \n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    \n    if not has_hard_evidence:\n\n        admission = get_val(ctx, \"入院记录\", {})\n\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否明确确诊为\'2型糖尿病\'？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：利拉鲁肽注射液限2型糖尿病患者使用，未发现相关诊断或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),   \n            \"name_evidence\": get_val(matched_names, \"诊断名称\"), \n            \"ai_result\": has_ai_evidence\n        }\n    )','','','利拉鲁肽注射液'),(24,'R-0011','使用乌司他丁须有急性胰腺炎、慢性复发性胰腺炎诊断','',1,'超限定用药','2026-06-29 09:11:21.542455','2026-06-29 09:11:45.413915','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"乌司他丁\", \"contains\")\n\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_list = get_val(ctx, \"诊断信息\")\n\n    matched_icd = filter_list(diag_list, \"ICD编码\", [\"K85\"], \"startswith\")\n\n    target_keywords = [\"急性胰腺炎\", \"慢性复发性胰腺炎\"]\n    matched_names = filter_list(diag_list, \"诊断名称\", target_keywords, \"contains\")\n\n    has_hard_evidence = (len(matched_icd) > 0) or (len(matched_names) > 0)\n\n    has_ai_evidence = False\n    \n    if not has_hard_evidence:\n        admission = get_val(ctx, \"入院记录\", {})\n        parts = [\n            f\"现病史: {get_val(admission, \'现病史\', \'\')}\",\n            f\"既往史: {get_val(admission, \'既往史\', \'\')}\",\n            f\"初步诊断: {get_val(admission, \'初步诊断\', \'\')}\"\n        ]\n        emr_context = \"; \".join(parts)\n\n        if len(emr_context) > 10:\n            has_ai_evidence = llm_bool(\n                context_text=emr_context,\n                question=\"患者是否确诊为\'急性胰腺炎\'或\'慢性复发性胰腺炎\'？\"\n            )\n\n    compliant = has_hard_evidence or has_ai_evidence\n    \n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：乌司他丁限\'急性胰腺炎\'或\'慢性复发性胰腺炎\'，未发现相关诊断(K85)或病史支持\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_drug\": get_val(target_items, \"药品通用名\"),\n            \"icd_evidence\": get_val(matched_icd, \"ICD编码\"),\n            \"name_evidence\": get_val(matched_names, \"诊断名称\"),\n            \"ai_result\": has_ai_evidence\n        }\n    )','','','乌司他丁'),(25,'R-0012','使用贝前列素须有慢性动脉闭塞诊断且有溃疡、间歇性跛行及严重疼痛体征症状','',1,'超限定用药','2026-06-29 09:11:39.375799','2026-06-29 09:11:45.980318','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"贝前列素\", \"contains\")\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_names = get_val(get_val(ctx, \"诊断信息\"), \"诊断名称\")\n    \n    admission = get_val(ctx, \"入院记录\")\n    txt_complaint = get_val(admission, \"主诉\", \"\")\n    txt_history = get_val(admission, \"现病史\", \"\")\n    txt_prelim = get_val(admission, \"初步诊断\", \"\")\n    emr_context = f\"主诉:{txt_complaint}; 现病史:{txt_history}; 初步诊断:{txt_prelim}\"\n\n    has_disease = list_contains(diag_names, \"慢性动脉闭塞\")\n    has_ulcer = list_contains(diag_names, \"溃疡\")\n    has_claudication = list_contains(diag_names, \"间歇性跛行\")\n    \n    is_hard_compliant = has_disease and has_ulcer and has_claudication\n\n    has_ai_evidence = False\n    if not is_hard_compliant and len(emr_context) > 5:\n        has_ai_evidence = llm_bool(\n            context_text=emr_context,\n            question=\"患者是否确诊为\'慢性动脉闭塞\'，且同时具备\'溃疡\'、\'间歇性跛行\'及\'严重疼痛\'这三个体征/症状？\"\n        )\n\n    compliant = is_hard_compliant or has_ai_evidence\n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：未同时满足慢性动脉闭塞诊断及溃疡、跛行、疼痛体征\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"drug_count\": len(target_items),\n            \"hard_match_components\": {\n                \"disease\": has_disease,\n                \"ulcer\": has_ulcer, \n                \"claudication\": has_claudication\n            },\n            \"ai_match\": has_ai_evidence\n        }\n    )','','','贝前列素'),(26,'R-0013','使用沙格雷酯须有慢性动脉闭塞诊断且有溃疡、间歇性跛行及严重疼痛体征症状','',1,'超限定用药','2026-06-29 09:12:15.106376','2026-06-29 09:12:15.106376','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"沙格雷酯\", \"contains\")\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_names = get_val(get_val(ctx, \"诊断信息\"), \"诊断名称\")\n    \n    admission = get_val(ctx, \"入院记录\")\n    txt_complaint = get_val(admission, \"主诉\", \"\")\n    txt_history = get_val(admission, \"现病史\", \"\")\n    txt_prelim = get_val(admission, \"初步诊断\", \"\")\n    emr_context = f\"主诉:{txt_complaint}; 现病史:{txt_history}; 初步诊断:{txt_prelim}\"\n\n    has_disease = list_contains(diag_names, \"慢性动脉闭塞\")\n    has_ulcer = list_contains(diag_names, \"溃疡\")\n    has_claudication = list_contains(diag_names, \"间歇性跛行\")\n    \n    is_hard_compliant = has_disease and has_ulcer and has_claudication\n\n    has_ai_evidence = False\n    if not is_hard_compliant and len(emr_context) > 5:\n        has_ai_evidence = llm_bool(\n            context_text=emr_context,\n            question=\"患者是否确诊为\'慢性动脉闭塞\'，且同时具备\'溃疡\'、\'间歇性跛行\'及\'严重疼痛\'这三个体征/症状？\"\n        )\n\n    compliant = is_hard_compliant or has_ai_evidence\n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：未同时满足慢性动脉闭塞诊断及溃疡、跛行、疼痛体征\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"drug_count\": len(target_items),\n            \"hard_match_components\": {\n                \"disease\": has_disease,\n                \"ulcer\": has_ulcer, \n                \"claudication\": has_claudication\n            },\n            \"ai_match\": has_ai_evidence\n        }\n    )','','','沙格雷酯'),(27,'R-0014','使用奥扎格雷须有急性血栓性脑梗死诊断且支付时间不超过14天','',1,'超限定用药','2026-06-29 09:12:34.633756','2026-06-29 09:12:34.633756','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"奥扎格雷\", \"contains\")\n    \n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    nested_records = get_val(target_items, \"开药信息\")\n\n    flat_records = [rec for sublist in nested_records if sublist for rec in sublist]\n\n    all_dates = get_val(flat_records, \"药品收费时间\")\n\n    days_span = calc_stats(all_dates, \"span_days\")\n    is_time_compliant = is_compare(days_span, \"<=\", 14)\n\n    diag_names = get_val(get_val(ctx, \"诊断信息\"), \"诊断名称\")\n    \n    admission = get_val(ctx, \"入院记录\")\n    txt_history = get_val(admission, \"现病史\", \"\")\n    txt_prelim = get_val(admission, \"初步诊断\", \"\")\n    emr_context = f\"现病史:{txt_history}; 初步诊断:{txt_prelim}\"\n\n    has_target_diag = list_contains(diag_names, \"急性血栓性脑梗死\")\n\n    has_ai_evidence = False\n    if is_time_compliant and not has_target_diag and len(emr_context) > 5:\n        has_ai_evidence = llm_bool(\n            context_text=emr_context,\n            # 强调三个要素必须同时存在，防止匹配到\"陈旧性\"或\"出血性\"\n            question=\"患者是否确诊为\'急性血栓性脑梗死\'？(注意：需同时满足\'急性\'、\'血栓性\'、\'脑梗死\'三个要素)\"\n        )\n\n    is_diag_compliant = has_target_diag or has_ai_evidence\n    compliant = is_time_compliant and is_diag_compliant\n    \n    fail_msg = \"\"\n    if not compliant:\n        if not is_time_compliant:\n            fail_msg = f\"用药疗程违规：奥扎格雷用药跨度({days_span}天)超过14天限制\"\n        else:\n            fail_msg = \"适应症不符：未发现急性血栓性脑梗死诊断\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"matched_codes\": get_val(target_items, \"药品国家编码\"),\n            \"days_span\": days_span,\n            \"time_list\": all_dates, # 证据中列出具体时间点\n            \"is_time_ok\": is_time_compliant,\n            \"hard_diag\": has_target_diag,\n            \"ai_diag\": has_ai_evidence\n        }\n    )','','','奥扎格雷'),(28,'R-0015','使用西洛他唑须有慢性动脉闭塞诊断且有溃疡、间歇性跛行及严重疼痛体征症状','',1,'超限定用药','2026-06-29 09:12:55.908574','2026-06-29 09:12:55.908574','def execute_rule(ctx):\n    med_list = get_val(ctx, \"用药信息\")\n    target_items = filter_list(med_list, \"药品通用名\", \"西洛他唑\", \"contains\")\n    if len(target_items) == 0:\n        return submit_result(is_applicable=False)\n\n    diag_names = get_val(get_val(ctx, \"诊断信息\"), \"诊断名称\")\n    \n    admission = get_val(ctx, \"入院记录\")\n    txt_complaint = get_val(admission, \"主诉\", \"\")\n    txt_history = get_val(admission, \"现病史\", \"\")\n    txt_prelim = get_val(admission, \"初步诊断\", \"\")\n    emr_context = f\"主诉:{txt_complaint}; 现病史:{txt_history}; 初步诊断:{txt_prelim}\"\n\n    has_disease = list_contains(diag_names, \"慢性动脉闭塞\")\n    has_ulcer = list_contains(diag_names, \"溃疡\")\n    has_claudication = list_contains(diag_names, \"间歇性跛行\")\n    \n    is_hard_compliant = has_disease and has_ulcer and has_claudication\n\n    has_ai_evidence = False\n    if not is_hard_compliant and len(emr_context) > 5:\n        has_ai_evidence = llm_bool(\n            context_text=emr_context,\n            question=\"患者是否确诊为\'慢性动脉闭塞\'，且同时具备\'溃疡\'、\'间歇性跛行\'及\'严重疼痛\'这三个体征/症状？\"\n        )\n\n    compliant = is_hard_compliant or has_ai_evidence\n    fail_msg = \"\"\n    if not compliant:\n        fail_msg = \"适应症不符：未同时满足慢性动脉闭塞诊断及溃疡、跛行、疼痛体征\"\n\n    return submit_result(\n        is_applicable=True,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"drug_count\": len(target_items),\n            \"hard_match_components\": {\n                \"disease\": has_disease,\n                \"ulcer\": has_ulcer, \n                \"claudication\": has_claudication\n            },\n            \"ai_match\": has_ai_evidence\n        }\n    )','','','西洛他唑'),(29,'R-0016','插胃管加收10元','',0,'超标准收费','2026-06-29 09:21:04.716218','2026-06-29 09:21:04.717218','def execute_rule(ctx):\n    fee_reports = get_val(ctx, \'收费报告\', default=[])\n    gastro_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'胃肠减压\',\n        operator=\'contains\'\n    )\n    target_items = filter_list(\n        data_list=gastro_items,\n        field_path=\'收费项目名称\',\n        match_value=\'插胃管\',\n        operator=\'contains\'\n    )\n    is_target = len(target_items) > 0\n    has_over_fee = False\n    over_items = []\n    if is_target:\n        for item in target_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=10):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee\n                })\n    applicable = is_target\n    compliant = False\n    fail_msg = \"\"\n    if applicable:\n        if has_over_fee:\n            # 构建详细违规信息\n            over_details = \', \'.join([\n                f\"{item[\'项目名称\']}: {item[\'项目单价\']}元\" \n                for item in over_items\n            ])\n            fail_msg = f\"发现胃肠减压插胃管项目单次收费超过10元: {over_details}\"\n        else:\n            compliant = True\n    \n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"目标项目数\": len(target_items),\n            \"存在超标项目\": has_over_fee,\n            \"超标项目详情\": over_items,\n            \"所有目标项目\": [\n                {\n                    \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                    \'项目单价\': get_val(item, \'项目单价\', default=0)\n                }\n                for item in target_items\n            ]\n        }\n    )','','','胃肠减压'),(30,'R-0017','原价79元，射频、激光、微波加收20元；等离子加收50元；冷冻减收55元','',0,'超标准收费','2026-06-29 09:24:30.676727','2026-06-29 09:24:30.676727','def execute_rule(ctx):\n    fee_reports = get_val(ctx, \'收费报告\', default=[])\n    ear_special_items = filter_list(data_list=fee_reports,field_path=\'收费项目名称\', match_value=\'耳部特殊治疗\',operator=\'contains\')\n    radio_items = filter_list(data_list=fee_reports,field_path=\'收费项目名称\',match_value=\'射频\',operator=\'contains\')\n    laser_items = filter_list(data_list=fee_reports,field_path=\'收费项目名称\',match_value=\'激光\',operator=\'contains\')\n    microwave_items = filter_list(data_list=fee_reports, field_path=\'收费项目名称\',match_value=\'微波\',operator=\'contains\')\n    plasma_items = filter_list(data_list=fee_reports,field_path=\'收费项目名称\',match_value=\'等离子\',operator=\'contains\')\n    freezing_items = filter_list(data_list=fee_reports, field_path=\'收费项目名称\', match_value=\'冷冻\',operator=\'contains\')\n    is_target = len(ear_special_items) > 0\n    has_over_fee = False\n    over_items = []\n\n    if is_target:\n        for item in radio_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=20):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'射频应为20元，实际{item_fee}元\'\n                })\n\n        # 检查激光项目单价是否为20元\n        for item in laser_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=20):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'激光应为20元，实际{item_fee}元\'\n                })\n\n        # 检查微波项目单价是否为20元\n        for item in microwave_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'==\', threshold=20):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'微波应为20元，实际{item_fee}元\'\n                })\n\n        # 检查等离子项目单价是否为50元\n        for item in plasma_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=50):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'等离子应为50元，实际{item_fee}元\'\n                })\n\n        # 检查冷冻项目单价是否为24元\n        for item in freezing_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=24):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'冷冻应为24元，实际{item_fee}元\'\n                })\n\n    applicable = is_target\n    compliant = False\n    fail_msg = \"\"\n\n    if applicable:\n        if has_over_fee:\n            over_details = \'; \'.join([\n                item[\'超标原因\']\n                for item in over_items\n            ])\n            fail_msg = f\"耳部特殊治疗及相关项目单价不符合规则: {over_details}\"\n        else:\n            compliant = True\n\n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"耳部特殊治疗项目数\": len(ear_special_items),\n            \"射频项目数\": len(radio_items),\n            \"激光项目数\": len(laser_items),\n            \"微波项目数\": len(microwave_items),\n            \"等离子项目数\": len(plasma_items),\n            \"冷冻项目数\": len(freezing_items),\n            \"存在超标项目\": has_over_fee,\n            \"超标项目详情\": over_items,\n            \"项目统计\": [\n                            {\n                                \'项目类型\': \'射频\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in radio_items\n                        ] + [\n                            {\n                                \'项目类型\': \'激光\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in laser_items\n                        ] + [\n                            {\n                                \'项目类型\': \'微波\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in microwave_items\n                        ] + [\n                            {\n                                \'项目类型\': \'等离子\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in plasma_items\n                        ] + [\n                            {\n                                \'项目类型\': \'冷冻\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in freezing_items\n                        ]\n        }\n    )','','','耳部特殊治疗'),(31,'R-0018','免疫化学法加收10元，色谱法加收15元','',0,'超标准收费','2026-06-29 09:24:58.463790','2026-06-29 09:27:05.567604','def execute_rule(ctx):\n        fee_reports = get_val(ctx, \'收费报告\', default=[])\n        hba1c_items = filter_list(\n            data_list=fee_reports,\n            field_path=\'收费项目名称\',\n            match_value=\'糖化血红蛋白测定\',\n            operator=\'contains\'\n        )\n        immuno_items = filter_list(\n            data_list=hba1c_items,\n            field_path=\'收费项目名称\',\n            match_value=\'免疫化学法\',\n            operator=\'contains\'\n        )\n        chromato_items = filter_list(\n            data_list=hba1c_items,\n            field_path=\'收费项目名称\',\n            match_value=\'色谱法\',\n            operator=\'contains\'\n        )\n        is_target = len(hba1c_items) > 0\n        has_over_fee = False\n        over_items = []\n\n        if is_target:\n            for item in immuno_items:\n                item_fee = get_val(item, \'项目单价\', default=0)\n                if is_compare(value=item_fee, operator=\'>\', threshold=10):\n                    has_over_fee = True\n                    item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                    over_items.append({\n                        \'项目名称\': item_name,\n                        \'项目单价\': item_fee,\n                        \'超标原因\': f\'免疫化学法应为10元，实际{item_fee}元\'\n                    })\n            for item in chromato_items:\n                item_fee = get_val(item, \'项目单价\', default=0)\n                if is_compare(value=item_fee, operator=\'>\', threshold=15):\n                    has_over_fee = True\n                    item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                    over_items.append({\n                        \'项目名称\': item_name,\n                        \'项目单价\': item_fee,\n                        \'超标原因\': f\'色谱法应为15元，实际{item_fee}元\'\n                    })\n\n        applicable = is_target\n        compliant = False\n        fail_msg = \"\"\n\n        if applicable:\n            if has_over_fee:\n                # 构建详细违规信息\n                over_details = \'; \'.join([\n                    item[\'超标原因\']\n                    for item in over_items\n                ])\n                fail_msg = f\"糖化血红蛋白测定加收不符合规则: {over_details}\"\n            else:\n                compliant = True\n\n        return submit_result(\n            is_applicable=is_target,\n            is_compliant=compliant,\n            failure_message=fail_msg,\n            evidence={\n                \"糖化血红蛋白测定项目数\": len(hba1c_items),\n                \"免疫化学法项目数\": len(immuno_items),\n                \"色谱法项目数\": len(chromato_items),\n                \"存在超标项目\": has_over_fee,\n                \"超标项目详情\": over_items,\n                \"项目统计\": [\n                                {\n                                    \'项目类型\': \'免疫化学法\',\n                                    \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                    \'项目单价\': get_val(item, \'项目单价\', default=0)\n                                }\n                                for item in immuno_items\n                            ] + [\n                                {\n                                    \'项目类型\': \'色谱法\',\n                                    \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                    \'项目单价\': get_val(item, \'项目单价\', default=0)\n                                }\n                                for item in chromato_items\n                            ]\n            }\n        )','','','糖化血红蛋白测定'),(32,'R-0019','原价760，陈旧性骨折加收120元；骨折合并脱位的加收60元；掌(跖)、指(趾)骨折按脱位的减收30元','',0,'超标准收费','2026-06-29 09:25:21.200603','2026-06-29 09:25:21.200603','def execute_rule(ctx):\n    fee_reports = get_val(ctx, \'收费报告\', default=[])\n    fracture_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'骨折手法整复术\',\n        operator=\'contains\'\n    )\n    old_fracture_items = filter_list(\n        data_list=fracture_items,\n        field_path=\'收费项目名称\',\n        match_value=\'陈旧性骨折\',\n        operator=\'contains\'\n    )\n    fracture_dislocation_items = filter_list(\n        data_list=fracture_items,\n        field_path=\'收费项目名称\',\n        match_value=[\'骨折合并脱位\', \'骨折脱位\'],\n        operator=\'contains\'\n    )\n\n    small_bone_items = filter_list(\n        data_list=fracture_items,\n        field_path=\'收费项目名称\',\n        match_value=[\'掌\', \'跖\', \'指\', \'趾\'],\n        operator=\'contains\'\n    )\n    normal_fracture_items = []\n    for item in fracture_items:\n        name = get_val(item, \'收费项目名称\', default=\'\')\n        # 排除特殊类型的骨折\n        if (\'陈旧性骨折\' not in name and\n                \'骨折合并脱位\' not in name and\n                \'骨折脱位\' not in name and\n                \'掌\' not in name and\n                \'跖\' not in name and\n                \'指\' not in name and\n                \'趾\' not in name):\n            normal_fracture_items.append(item)\n    is_target = len(fracture_items) > 0\n    has_over_fee = False\n    over_items = []\n    if is_target:\n        for item in old_fracture_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=120):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'陈旧性骨折超过120元，实际{item_fee}元\'\n                })\n        for item in fracture_dislocation_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=60):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'骨折合并脱位超过60元，实际{item_fee}元\'\n                })\n        for item in small_bone_i