             for item in fracture_dislocation_items\n                        ] + [\n                            {\n                                \'项目类型\': \'掌(跖)指(趾)骨折\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in small_bone_items\n                        ]\n        }\n    )','','','骨折手法整复术'),(33,'R-0020','使用洗胃机加收20元','',0,'超标准收费','2026-06-29 09:27:01.668265','2026-06-29 09:27:01.668265','def execute_rule(ctx):\n    fee_reports = get_val(ctx, \'收费报告\', default=[])\n    gastric_lavage_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'洗胃\',\n        operator=\'contains\'\n    )\n    machine_items = filter_list(\n        data_list=gastric_lavage_items,\n        field_path=\'收费项目名称\',\n        match_value=\'洗胃机\',\n        operator=\'contains\'\n    )\n    is_target = len(gastric_lavage_items) > 0\n    has_over_fee = False\n    over_items = []\n    if is_target:\n        for item in machine_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=20):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee,\n                    \'超标原因\': f\'使用洗胃机超过20元，实际{item_fee}元\'\n                })\n    applicable = is_target\n    compliant = False\n    fail_msg = \"\"\n    if applicable:\n        if has_over_fee:\n            over_details = \'; \'.join([\n                item[\'超标原因\']\n                for item in over_items\n            ])\n            fail_msg = f\"洗胃项目收费超标: {over_details}\"\n        else:\n            compliant = True\n\n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"洗胃项目总数\": len(gastric_lavage_items),\n            \"使用洗胃机项目数\": len(machine_items),\n            \"存在超标项目\": has_over_fee,\n            \"超标项目详情\": over_items,\n            \"项目统计\": [\n                            {\n                                \'项目类型\': \'使用洗胃机\',\n                                \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                                \'项目单价\': get_val(item, \'项目单价\', default=0)\n                            }\n                            for item in machine_items\n                        ]\n        }\n    )','','','洗胃'),(34,'R-0021','传染病和特异性感染病尸体加收160元。','',0,'超标准收费','2026-06-29 09:27:42.118218','2026-06-29 09:27:42.118218','def execute_rule(ctx):\n    fee_reports = get_val(ctx, \'收费报告\', default=[])\n    autopsy_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'尸检病理诊断\',\n        operator=\'contains\'\n    )\n    infectious_items = filter_list(\n        data_list=autopsy_items,\n        field_path=\'收费项目名称\',\n        match_value=[\'传染病\', \'特异性感染\'],\n        operator=\'contains\'\n    )\n    is_target = len(autopsy_items) > 0\n    has_over_fee = False\n    over_items = []\n    if is_target:\n        for item in infectious_items:\n            item_fee = get_val(item, \'项目单价\', default=0)\n            if is_compare(value=item_fee, operator=\'>\', threshold=160):\n                has_over_fee = True\n                item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                over_items.append({\n                    \'项目名称\': item_name,\n                    \'项目单价\': item_fee\n                })\n    \n    applicable = is_target\n    compliant = False\n    fail_msg = \"\"\n    if applicable:\n        if has_over_fee:\n            over_details = \', \'.join([\n                f\"{item[\'项目名称\']}: {item[\'项目单价\']}元\" \n                for item in over_items\n            ])\n            fail_msg = f\"发现传染病/特异性感染病尸体项目单次收费超过160元: {over_details}\"\n        else:\n            compliant = True\n    \n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"尸检病理诊断项目数\": len(autopsy_items),\n            \"传染病/特异性感染病尸体项目数\": len(infectious_items),\n            \"存在超标项目\": has_over_fee,\n            \"超标项目详情\": over_items,\n            \"所有传染病/特异性感染病尸体项目\": [\n                {\n                    \'项目名称\': get_val(item, \'收费项目名称\', default=\'\'),\n                    \'项目单价\': get_val(item, \'项目单价\', default=0)\n                }\n                for item in infectious_items\n            ]\n        }\n    )','','','尸检病理诊断'),(35,'R-0022','酶免法加收15元，流式细胞仪法加收30元','',0,'超标准收费','2026-06-29 09:28:21.110568','2026-06-29 09:28:21.110568','def execute_rule(ctx):\n        fee_reports = get_val(ctx, \'收费报告\', default=[])\n        leukemia_items = filter_list(\n            data_list=fee_reports,\n            field_path=\'收费项目名称\',\n            match_value=\'白血病免疫分型\',\n            operator=\'contains\'\n        )\n        enzyme_items = filter_list(\n            data_list=leukemia_items,\n            field_path=\'收费项目名称\',\n            match_value=\'酶免法\',\n            operator=\'contains\'\n        )\n\n        flow_cytometry_items = filter_list(\n            data_list=leukemia_items,\n            field_path=\'收费项目名称\',\n            match_value=\'流式细胞仪法\',\n            operator=\'contains\'\n        )\n        is_target = len(leukemia_items) > 0\n        has_over_fee = False\n        over_items = []\n\n        if is_target:\n            for item in enzyme_items:\n                item_fee = get_val(item, \'项目单价\', default=0)\n                if is_compare(value=item_fee, operator=\'>\', threshold=15):\n                    has_over_fee = True\n                    item_name = get_val(item, \'收费项目名称\', default=\'未知项目\