 get_val(item, \'收费项目名称\', default=\'\'),\n                                        \'项目单价\': get_val(item, \'项目单价\', default=0),\n                                        \'项目类型\': \'流式细胞仪法\'\n                                    }\n                                    for item in flow_cytometry_items\n                                ]\n            }\n        )','','','白血病免疫分型'),(36,'R-0023','仪器法 加收5元','',0,'超标准收费','2026-06-29 09:29:16.019974','2026-06-29 09:29:16.019974','def execute_rule(ctx):\n        fee_reports = get_val(ctx, \'收费报告\', default=[])\n        tt_items = filter_list(\n            data_list=fee_reports,\n            field_path=\'收费项目名称\',\n            match_value=[\'凝血酶时间测定\', \'TT测定\'],\n            operator=\'contains\'\n        )\n        instrument_items = filter_list(\n            data_list=tt_items,\n            field_path=\'收费项目名称\',\n            match_value=\'仪器法\',\n            operator=\'contains\'\n        )\n\n        is_target = len(tt_items) > 0\n        has_over_fee = False\n        over_items = []\n\n        if is_target:\n            for item in instrument_items:\n                item_fee = get_val(item, \'项目单价\', default=0)\n                if is_compare(value=item_fee, operator=\'>\', threshold=5):\n                    has_over_fee = True\n                    item_name = get_val(item, \'收费项目名称\', default=\'未知项目\')\n                    over_items.append({\n                        \'项目名称\': item_name,\n                        \'项目单价\': item_fee\n                    })\n\n        applicable = is_target\n        compliant = False\n        fail_msg = \"\"\n\n        if applicable:\n            if has_over_fee:\n                over_details = \', \'.join([\n                    f\"{item[\'项目名称\']}: {item[\'项目单价\']}元\"\n                    for item in over_items\n                ])\n                fail_msg = f\"发现凝血酶时间测定仪器法项目单次收费超过5元: {over_details}\"\n            else:\n                compliant = True\n\n        return submit_result(\n   