声检查术(IVUS){conflict[\'ivus_count\']}项, 冠状动脉造影术{conflict[\'coronary_angiography_count\']}项\"\n            )\n        fail_msg = f\"冠脉血管内超声检查术(IVUS)与冠状动脉造影术在同一秒内同时开具，冲突时间点：{\'；\'.join(conflict_details)}\"\n\n    return {\n        \"is_applicable\": is_target,\n        \"is_compliant\": compliant,\n        \"failure_message\": fail_msg,\n        \"evidence\": {\n            \"total_ivus_count\": len(ivus_items),\n            \"total_coronary_angiography_count\": len(coronary_angiography_items),\n            \"conflict_times\": conflict_times,\n            \"ivus_items\": ivus_items,\n            \"coronary_angiography_items\": coronary_angiography_items\n        }\n    }','','','冠脉血管内超声检查术(IVUS)'),(45,'R-0032','“冠脉内局部药物释放治疗术”与“冠状动脉造影术”不能同时开','',0,'重复收费','2026-06-29 09:35:18.581546','2026-06-29 09:35:18.581546','def execute_rule(ctx):\n    fees = get_val(ctx, \"收费报告\", default=[])\n\n    intracoronary_local_drug_release_items = filter_list(\n        data_list=fees,\n        field_path=\'收费项目名称\',\n        match_value=\'冠脉内局部药物释放治疗术\',\n        operator=\'contains\'\n    )\n    coronary_angiography_items = filter_list(\n        data_list=fees,\n        field_path=\'收费项目名称\',\n        match_value=\'冠状动脉造影术\',\n        operator=\'contains\'\n    )\n\n    time_grouped_drug_release = {}\n    time_grouped_angiography = {}\n\n    for item in intracoronary_local_drug_release_items:\n        charge_time = item.get(\'收费日期\', \'\')\n        if charge_time:\n            time_key = charge_time[:19]\n            time_grouped_drug_release.setdefault(time_key, []).append(item)\n\n    for item in coronary_angiography_items:\n        charge_time = item.get(\'收费日期\', \'\')\n        if charge_time:\n            time_key = charge_time[:19]\n            time_grouped_angiography.setdefault(time_key, []).append(item)\n\n    conflict_times = []\n    for time_key in time_grouped_drug_release:\n        if time_key in time_grouped_angiography:\n            conflict_times.append({\n                \"time\": time_key,\n                \"intracoronary_local_drug_release_count\": len(time_grouped_drug_release[time_key]),\n                \"coronary_angiography_count\": len(time_grouped_angiography[time_key])\n            })\n\n    is_target = len(intracoronary_local_drug_release_items) > 0 or len(coronary_angiography_items) > 0\n    compliant = len(conflict_times) == 0\n\n    fail_msg = \"\"\n    if is_target and not compliant:\n        conflict_details = []\n        for conflict in conflict_times:\n            conflict_details.append(\n                f\"{conflict[\'time\']}: 冠脉内局部药物释放治疗术{conflict[\'intracoronary_local_drug_release_count\']}项, 冠状动脉造影术{conflict[\'coronary_angiography_count\']}项\"\n            )\n        fail_msg = f\"冠脉内局部药物释放治疗术与冠状动脉造影术在同一秒内同时开具，冲突时间点：{\'；\'.join(conflict_details)}\"\n\n    return {\n        \"is_applicable\": is_target,\n        \"is_compliant\": compliant,\n        \"failure_message\": fail_msg,\n        \"evidence\": {\n            \"total_intracoronary_local_drug_release_count\": len(intracoronary_local_drug_release_items),\n            \"total_coronary_angiography_count\": len(coronary_angiography_items),\n            \"conflict_times\": conflict_times,\n            \"intracoronary_local_drug_release_items\": intracoronary_local_drug_release_items,\n            \"coronary_angiography_items\": coronary_angiography_items\n        }\n    }','','','冠脉内局部药物释放治疗术'),(46,'R-0033','“泪小点扩张”与“泪道冲洗”不能同时开','',0,'重复收费','2026-06-29 09:35:49.564699','2026-06-29 09:35:49.564699','def execute_rule(ctx):\n    fees = get_val(ctx, \"收费报告\", default=[])\n\n    lacrimal_punctum_dilation_items = filter_list(\n        data_list=fees,\n        field_path=\'收费项目名称\',\n        match_value=\'泪小点扩张\',\n        operator=\'contains\'\n    )\n    lacrimal_duct_irrigation_items = filter_list(\n        data_list=fees,\n        field_path=\'收费项目名称\',\n        match_value=\'泪道冲洗\',\n        operator=\'contains\'\n    )\n\n    time_grouped_dilation = {}\n    time_grouped_irrigation = {}\n\n    for item in lacrimal_punctum_dilation_items:\n        charge_time = item.get(\'收费日期\', \'\')\n        if charge_time:\n            time_key = charge_time[:19]\n            time_grouped_dilation.setdefault(time_key, []).append(item)\n\n    for item in lacrimal_duct_irrigation_items:\n        charge_time = item.get(\'收费日期\', \'\')\n        if charge_time:\n            time_key = charge_time[:19]\n            time_grouped_irrigation.setdefault(time_key, []).append(item)\n\n    conflict_times = []\n    for time_key in time_grouped_dilation:\n        if time_key in time_grouped_irrigation:\n            conflict_times.append({\n                \"time\": time_key,\n                \"lacrimal_punctum_dilation_count\": len(time_grouped_dilation[time_key]),\n                \"lacrimal_duct_irrigation_count\": len(time_grouped_irrigation[time_key])\n            })\n\n    is_target = len(lacrimal_punctum_dilation_items) > 0 or len(lacrimal_duct_irrigation_items) > 0\n    compliant = len(conflict_times) == 0\n\n    fail_msg = \"\"\n    if is_target and not compliant:\n        conflict_details = []\n        for conflict in conflict_times:\n            conflict_details.append(\n                f\"{conflict[\'time\']}: 泪小点扩张{conflict[\'lacrimal_punctum_dilation_count\']}项, \"\n                f\"泪道冲洗{conflict[\'lacrimal_duct_irrigation_count\']}项\"\n            )\n        fail_msg = f\"泪小点扩张与泪道冲洗在同一秒内同时开具，冲突时间点：{\'；\'.join(conflict_details)}\"\n\n    return {\n        \"is_applicable\": is_target,\n        \"is_compliant\": compliant,\n        \"failure_message\": fail_msg,\n        \"evidence\": {\n            \"total_lacrimal_punctum_dilation_count\": len(lacrimal_punctum_dilation_items),\n            \"total_lacrimal_duct_irrigation_count\": len(lacrimal_duct_irrigation_items),\n            \"conflict_times\": conflict_times,\n            \"lacrimal_punctum_dilation_items\": lacrimal_punctum_dilation_items,\n            \"lacrimal_duct_irrigation_items\": lacrimal_duct_irrigation_items\n        }\n    }','','','泪小点扩张'),(47,'R-0034','机械辅助排痰使用项目的数量总计超过上限数量，单日上限数量1，项目收费单位日','',0,'超频次收费','2026-06-29 09:39:18.438009','2026-06-29 09:40:57.484230','def execute_rule(ctx):\n    # Phase 1: Prepare Data\n    fee_reports = get_val(ctx, \"收费报告\", default=[])\n    target_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'机械辅助排痰\',\n        operator=\'==\'\n    )\n    \n    # Extract relevant fields and group by date\n    daily_counts = {}\n    for item in target_items:\n        charge_date = get_val(item, \'收费日期\', default=\'\')\n        if not charge_date:\n            continue\n        # Extract date part (YYYY-MM-DD)\n        date_key = charge_date[:10]\n        unit = get_val(item, \'项目单位\', default=\'\')\n        quantity = get_val(item, \'项目数量\', default=0)\n        quantity = float(quantity)\n        if unit in [\'日\', \'天\', \'day\', \'Day\', \'D\']:\n            daily_counts[date_key] = daily_counts.get(date_key, 0) + quantity\n    # Phase 2: Predicates\n    is_target = len(target_items) > 0\n    has_excess = False\n    excess_details = []\n    for date_key, total_qty in daily_counts.items():\n        if is_compare(value=total_qty, operator=\'>\', threshold=1):\n            has_excess = True\n            excess_details.append({\n                \"日期\": date_key,\n                \"总计数量\": total_qty,\n                \"上限\": 1\n            })\n    \n    # Phase 3: Logic & Result\n    applicable = is_target\n    compliant = not has_excess\n    fail_msg = \"\"\n    \n    if applicable and not compliant:\n        detail_strs = [\n            f\"{item[\'日期\']}: 实际{item[\'总计数量\']}日，超上限{item[\'上限\']}日\"\n            for item in excess_details\n        ]\n        fail_msg = f\"机械辅助排痰项目单日上限为1日，发现超限记录：{\'；\'.join(detail_strs)}。项目收费单位为日，仅统计单位为\'日\'或\'天\'的收费记录。\"\n    \n    return submit_result(\n        is_applicable=applicable,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"目标项目总数\": len(target_items),\n            \"每日使用统计\": daily_counts,\n            \"超限记录数\": len(excess_details),\n            \"超限详情\": excess_details,\n            \"所有目标项目\": [\n                {\n                    \"收费日期\": get_val(item, \'收费日期\', default=\'\'),\n                    \"项目数量\": get_val(item, \'项目数量\', default=0),\n                    \"项目单位\": get_val(item, \'项目单位\', default=\'\')\n                }\n                for item in target_items\n            ]\n        }\n    )','','','机械辅助排痰'),(48,'R-0035','使用项目的数量总计超过上限数量，单日上限数量1，项目收费单位日','',0,'超频次收费','2026-06-29 09:41:43.906030','2026-06-29 09:41:43.906030','def execute_rule(ctx):\n    # Phase 1: Prepare Data\n    fee_reports = get_val(ctx, \"收费报告\", default=[])\n    target_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'胃肠减压\',\n        operator=\'==\'\n    )\n    # Extract relevant fields and group by date\n    daily_counts = {}\n    for item in target_items:\n        charge_date = get_val(item, \'收费日期\', default=\'\')\n        if not charge_date:\n            continue\n        # Extract date part (YYYY-MM-DD)\n        date_key = charge_date[:10]\n        unit = get_val(item, \'项目单位\', default=\'\')\n        quantity = get_val(item, \'项目数量\', default=0)\n        quantity = float(quantity)\n        if unit in [\'日\', \'天\', \'day\', \'Day\', \'D\']:\n            daily_counts[date_key] = daily_counts.get(date_key, 0) + quantity\n    # Phase 2: Predicates\n    is_target = len(target_items) > 0\n    has_excess = False\n    excess_details = []\n    for date_key, total_qty in daily_counts.items():\n        if is_compare(value=total_qty, operator=\'>\', threshold=1):\n            has_excess = True\n            excess_details.append({\n                \"日期\": date_key,\n                \"总计数量\": total_qty,\n                \"上限\": 1\n            })\n    \n    # Phase 3: Logic & Result\n    applicable = is_target\n    compliant = not has_excess\n    fail_msg = \"\"\n    \n    if applicable and not compliant:\n        detail_strs = [\n            f\"{item[\'日期\']}: 实际{item[\'总计数量\']}日，超上限{item[\'上限\']}日\"\n            for item in excess_details\n        ]\n        fail_msg = f\"胃肠减压项目单日上限为1日，发现超限记录：{\'；\'.join(detail_strs)}。项目收费单位为日，仅统计单位为\'日\'或\'天\'的收费记录。\"\n    \n    return submit_result(\n        is_applicable=applicable,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"目标项目总数\": len(target_items),\n            \"每日使用统计\": daily_counts,\n            \"超限记录数\": len(excess_details),\n            \"超限详情\": excess_details,\n            \"所有目标项目\": [\n                {\n                    \"收费日期\": get_val(item, \'收费日期\', default=\'\'),\n                    \"项目数量\": get_val(item, \'项目数量\', default=0),\n                    \"项目单位\": get_val(item, \'项目单位\', default=\'\')\n                }\n                for item in target_items\n            ]\n        }\n    )','','','胃肠减压'),(49,'R-0036','血氧饱和度监测使用项目的数量总计超过上限数量，单日上限数量24，项目收费单位小时','',0,'超频次收费','2026-06-29 09:42:14.893979','2026-06-29 09:42:14.893979','def execute_rule(ctx):\n    # Phase 1: Prepare Data\n    fee_reports = get_val(ctx, \"收费报告\", default=[])\n    target_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'血氧饱和度监测\',\n        operator=\'==\'\n    )\n    # Extract relevant data: charge date and quantity (project quantity is in hours)\n    daily_counts = {}\n    for item in target_items:\n        charge_date = get_val(item, \"收费日期\", default=\"\")\n        if not charge_date:\n            continue\n        # Extract date part (YYYY-MM-DD) for daily grouping\n        date_key = charge_date[:10]\n        quantity = get_val(item, \"项目数量\", default=0)\n        unit = get_val(item, \'项目单位\', default=\'\')\n        # Ensure quantity is numeric\n        if isinstance(quantity, str):\n            try:\n                quantity = float(quantity)\n            except ValueError:\n                quantity = 0\n        daily_counts.setdefault(date_key, 0)\n        if unit in [\'小时\', \'时\', \'hour\', \'h\', \'H\']:\n            daily_counts[date_key] += quantity\n    \n    # Phase 2: Predicates\n    is_target = len(target_items) > 0\n    daily_max_limit = 24\n    \n    # Find all days where usage exceeds limit\n    violation_days = []\n    for date_key, total_hours in daily_counts.items():\n        if is_compare(value=total_hours, operator=\'>\', threshold=daily_max_limit):\n            violation_days.append({\n                \"date\": date_key,\n                \"total_hours\": total_hours,\n                \"limit\": daily_max_limit\n            })\n    \n    # Phase 3: Logic & Result\n    compliant = len(violation_days) == 0\n    fail_msg = \"\"\n    \n    if is_target and not compliant:\n        violation_details = []\n        for v in violation_days:\n            violation_details.append(\n                f\"{v[\'date\']}: 实际{v[\'total_hours\']}小时，超出上限{v[\'limit\']}小时\"\n            )\n        fail_msg = f\"血氧饱和度监测单日使用时长超限：{\'；\'.join(violation_details)}\"\n    \n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"total_target_items\": len(target_items),\n            \"daily_usage\": daily_counts,\n            \"exceeded_days\": violation_days,\n            \"daily_limit\": daily_max_limit,\n            \"target_items\": [\n                {\n                    \"收费日期\": get_val(item, \"收费日期\", default=\"\"),\n                    \"项目数量\": get_val(item, \"项目数量\", default=0),\n                    \"项目单位\": get_val(item, \"项目单位\", default=\"\")\n                }\n                for item in target_items\n            ]\n        }\n    )','','','血氧饱和度监测'),(50,'R-0037','使用项目的数量总计超过上限数量，单日上限数量1，项目收费单位日','',0,'超频次收费','2026-06-29 09:42:33.275789','2026-06-29 09:42:47.872039','def execute_rule(ctx):\n    # Phase 1: Prepare Data\n    fee_reports = get_val(ctx, \"收费报告\", default=[])\n    target_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=[\'普通病房床位费(三人)\',\'普通病房床位费(三人房)\']\n        operator=\'in\'\n    )\n    \n    # Extract relevant fields and group by date\n    daily_counts = {}\n    for item in target_items:\n        charge_date = get_val(item, \'收费日期\', default=\'\')\n        if not charge_date:\n            continue\n        # Extract date part (YYYY-MM-DD)\n        date_key = charge_date[:10]\n        unit = get_val(item, \'项目单位\', default=\'\')\n        quantity = get_val(item, \'项目数量\', default=0)\n        quantity = float(quantity)\n        if unit in [\'日\', \'天\', \'day\', \'Day\', \'D\']:\n            daily_counts[date_key] = daily_counts.get(date_key, 0) + quantity\n    # Phase 2: Predicates\n    is_target = len(target_items) > 0\n    has_excess = False\n    excess_details = []\n    for date_key, total_qty in daily_counts.items():\n        if is_compare(value=total_qty, operator=\'>\', threshold=1):\n            has_excess = True\n            excess_details.append({\n                \"日期\": date_key,\n                \"总计数量\": total_qty,\n                \"上限\": 1\n            })\n    \n    # Phase 3: Logic & Result\n    applicable = is_target\n    compliant = not has_excess\n    fail_msg = \"\"\n    \n    if applicable and not compliant:\n        detail_strs = [\n            f\"{item[\'日期\']}: 实际{item[\'总计数量\']}日，超上限{item[\'上限\']}日\"\n            for item in excess_details\n        ]\n        fail_msg = f\"普通病房床位费(三人)项目单日上限为1日，发现超限记录：{\'；\'.join(detail_strs)}。项目收费单位为日，仅统计单位为\'日\'或\'天\'的收费记录。\"\n    \n    return submit_result(\n        is_applicable=applicable,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"目标项目总数\": len(target_items),\n            \"每日使用统计\": daily_counts,\n            \"超限记录数\": len(excess_details),\n            \"超限详情\": excess_details,\n            \"所有目标项目\": [\n                {\n                    \"收费日期\": get_val(item, \'收费日期\', default=\'\'),\n                    \"项目数量\": get_val(item, \'项目数量\', default=0),\n                    \"项目单位\": get_val(item, \'项目单位\', default=\'\')\n                }\n                for item in target_items\n            ]\n        }\n    )','','','三人床'),(51,'R-0038','使用项目的数量总计超过上限数量，单日上限数量1，项目收费单位日','',0,'超频次收费','2026-06-29 09:43:13.944568','2026-06-29 09:43:13.944568','def execute_rule(ctx):\n    # Phase 1: Prepare Data\n    fee_reports = get_val(ctx, \"收费报告\", default=[])\n    target_items = filter_list(\n        data_list=fee_reports,\n        field_path=\'收费项目名称\',\n        match_value=\'住院诊查费\',\n        operator=\'==\'\n    )\n    \n    # Extract relevant fields and group by date\n    daily_counts = {}\n    for item in target_items:\n        charge_date = get_val(item, \'收费日期\', default=\'\')\n        if not charge_date:\n            continue\n        # Extract date part (YYYY-MM-DD)\n        date_key = charge_date[:10]\n        unit = get_val(item, \'项目单位\', default=\'\')\n        quantity = get_val(item, \'项目数量\', default=0)\n        quantity = float(quantity)\n        if unit in [\'日\', \'天\', \'day\', \'Day\', \'D\']:\n            daily_counts[date_key] = daily_counts.get(date_key, 0) + quantity\n    # Phase 2: Predicates\n    is_target = len(target_items) > 0\n    has_excess = False\n    excess_details = []\n    for date_key, total_qty in daily_counts.items():\n        if is_compare(value=total_qty, operator=\'>\', threshold=1):\n            has_excess = True\n            excess_details.append({\n                \"日期\": date_key,\n                \"总计数量\": total_qty,\n                \"上限\": 1\n            })\n    \n    # Phase 3: Logic & Result\n    applicable = is_target\n    compliant = not has_excess\n    fail_msg = \"\"\n    \n    if applicable and not compliant:\n