 f\"连续性血液净化单日使用时长超限：{\'；\'.join(violation_details)}\"\n    \n    return submit_result(\n        is_applicable=is_target,\n        is_compliant=compliant,\n        failure_message=fail_msg,\n        evidence={\n            \"total_target_items\": len(target_items),\n            \"daily_usage\": daily_counts,\n            \"exceeded_days\": violation_days,\n            \"daily_limit\": daily_max_limit,\n            \"target_items\": [\n                {\n                    \"收费日期\": get_val(item, \"收费日期\", default=\"\"),\n                    \"项目数量\": get_val(item, \"项目数量\", default=0),\n                    \"项目单位\": get_val(item, \"项目单位\", default=\"\")\n                }\n                for item in target_items\n            ]\n        }\n    )','','','连续性血液净化'),(55,'R-0042','收取“血气分析”费用的同时收取“血清碳酸氢盐(HCO3)测定”费用','',0,'过度医疗','2026-06-29 09:50:32.769350','2026-06-29 09:50:32.769350','','','','血气分析'),(56,'R-0043','收取尿液分析费用时，同时收取尿沉渣白细胞分类费用或尿蛋白定量费用','',0,'过度医疗','2026-06-29 09:51:06.777724','2026-06-29 09:51:06.777724','','','','尿液分析'),(57,'R-0044','同一患者在90天内多次开展并收费','',0,'过度医疗','2026-06-29 09:51:56.330009','2026-06-29 09:51:56.330009','','','','糖化血红蛋白测定'),(58,'R-0045','同一天用多种检测方法进行测定','',0,'过度医疗','2026-06-29 09:52:36.675518','2026-07-04 13:58:18.575080','def execute_rule(ctx):\n    fees = get_val(ctx, \"收费报告\", default=[])\n    \n    # 获取患者信息\n    patient_id = get_val(ctx, \"患者编号\", default=\"\")\n    \n    # 筛选\"葡萄糖测定\"项目\n    glucose_items = filter_list(\n        data_list=fees,\n        field_path=\'收费项目名称\',\n        match_value=\'葡萄糖测定\',\n        operator=\'contains\'\n    )\n    \n    # 按日期分组，记录每个日期下使用的检测方法\n    date_methods = {}  # {日期: {方法1: [项目列表], 方法2: [项目列表]}}\n    \n    for item in glucose_items:\n        charge_time = item.get(\'收费日期\', \'\')\n        if not charge_time:\n            continue\n        \n        date_key = charge_time[:10]  # 精确到天\n        item_name = item.get(\'收费项目名称\', \'\')\n        \n        # 提取检测方法（重点识别干化学法和酶电极法）\n        method = extract_glucose_method(item_name)\n        \n        if date_key not in date_methods:\n            date_methods[date_key] = {}\n        if method not in date_methods[date_key]:\n            date_methods[date_key][method] = []\n        date_methods[date_key][method].append(item)\n    \n    # 找出同日使用\"干化学法\"和\"酶电极法\"的违规日期\n    violation_dates = {}\n    for date_key, methods_dict in date_methods.items():\n        methods_list = list(methods_dict.keys())\n        \n        # 检查是否同时包含干化学法和酶电极法\n        has_dry_chem = any(\'干化学\' in m for m in methods_list)\n        has_enzyme_electrode = any(\'酶电极\' in m or \'电极\' in m for m in methods_list)\n        \n        if has_dry_chem and has_enzyme_electrode:\n            violation_dates[date_key] = {\n                \"methods\": methods_list,\n                \"method_counts\": {m: len(items) for m, items in methods_dict.items()},\n                \"total_count\": sum(len(items) for items in methods_dict.values())\n            }\n    \n    is_target = len(glucose_items) > 0\n    is_compliant = len(violation_dates) == 0\n    \n    fail_msg = \"\"\n    if is_target and not is_compliant:\n        violation_details = []\n        for date, info in sorted(violation_dates.items()):\n            method_detail = []\n            for method, count in info[\'method_counts\'].items():\n                method_detail.append(f\"{method}({count}次)\")\n            violation_details.append(\n                f\"{date}: 同时使用干化学法和酶电极法测定葡萄糖，\"\n                f\"具体为{\'、\'.join(method_detail)}，共{info[\'total_count\']}次\"\n            )\n        \n        fail_msg = (\n            f\"患者在同一天内使用\'干化学法\'和\'酶电极法\'两种方法进行\'葡萄糖测定\'，\"\n            f\"涉及{len(violation_dates)}个违规日期。\"\n            f\"明细：{\'；\'.join(violation_details)}\"\n        )\n    \n    return {\n        \"is_applicable\": is_target,\n        \"is_compliant\": is_compliant,\n        \"failure_message\": fail_msg,\n        \"evidence\": {\n            \"patient_id\": patient_id,\n            \"total_glucose_count\": len(glucose_items),\n            \"date_methods\": date_methods,\n            \"violation_dates\": violation_dates,\n            \"all_items\": glucose_items\n        }\n    }','','','葡萄糖测定'),(59,'R-0046','对同一患者同日多次开展并纳入医保报销','',0,'过度医疗','2026-06-29 09:53:42.150937','2026-06-29 09:53:42.150937','','','','血清天门冬氨酸氨基转移酶测定'),(60,'imp_8_2','限有十二指肠溃疡、反流性食管炎诊断患者的二线用药','',1,'超限定用药','2026-06-30 09:21:37.439769','2026-06-30 09:21:37.439769','','收费项目名称','艾普拉唑','艾普拉唑'),(61,'imp_8_3','限活动性十二指肠溃疡或胃食管反流病。','',1,'超限定用药','2026-06-30 09:21:37.446860','2026-06-30 09:21:37.446860','','收费项目名称','奥美拉唑碳酸氢钠干混悬剂 (Ⅰ)','奥美拉唑碳酸氢钠干混悬剂 (Ⅰ)'),(62,'imp_8_5','限胃肠镜检查和腹部影像学检查','',1,'超限定用药','2026-06-30 09:21:37.451861','2026-06-30 09:21:37.451861','','收费项目名称','二甲硅油','二甲硅油'),(63,'imp_8_6','限胃肠镜检查和腹部影像学检查','',1,'超限定用药','2026-06-30 09:21:37.455860','2026-06-30 09:21:37.455860','','收费项目名称','西甲硅油','西甲硅油'),(64,'imp_8_7','限 AST 或 ALT 大于 120U/L 的患者','',1,'超限定用药','2026-06-30 09:21:37.469872','2026-06-30 09:21:37.469872','','收费项目名称','促肝细胞生长素','促肝细胞生长素'),(65,'imp_8_8','限 AST 或 ALT 大于 120U/L 的患者','',1,'超限定用药','2026-06-30 09:21:37.476459','2026-06-30 09:21:37.476459','','收费项目名称','多烯磷脂酰胆碱','多烯磷脂酰胆碱'),(66,'imp_8_9','限 AST 或 ALT 大于 120U/L 的患者','',1,'超限定用药','2026-06-30 09:21:37.480460','2026-06-30 09:21:37.480460','','收费项目名称','复方甘草甜素 (复方甘草酸苷)','复方甘草甜素 (复方甘草酸苷)'),(67,'imp_8_10','限 AST 或 ALT 大于 120U/L 的患者','',1,'超限定用药','2026-06-30 09:21:37.489338','2026-06-30 09:21:37.489338','','收费项目名称','甘草酸二铵','甘草酸二铵'),(68,'imp_8_11','限肝功能异常患者','',1,'超限定用药','2026-06-30 09:21:37.496859','2026-06-30 09:21:37.496859','','收费项目名称','谷胱甘肽','谷胱甘肽'),(69,'imp_8_12','限 AST 或 ALT 大于 120U/L 的患者','',1,'超限定用药','2026-06-30 09:21:37.503860','2026-06-30 09:21:37.503860','','收费项目名称','还原型谷胱甘肽 (谷胱甘肽)','还原型谷胱甘肽 (谷胱甘肽)'),(70,'imp_8_13','限血氨升高或肝性脑病的患者','',1,'超限定用药','2026-06-30 09:21:37.513869','2026-06-30 09:21:37.513869','','收费项目名称','门冬氨酸鸟氨酸','门冬氨酸鸟氨酸'),(71,'imp_8_14','AST 或 ALT 大于 120U/L','',1,'超限定用药','2026-06-30 09:21:37.520866','20