INSERT INTO `sql_analysis_sqlrule` VALUES (1,'test1','超频次','111111','SELECT INHOS_NO AS 住院号,\n		 DATE(CHRG_DT) AS 收费日期,\n		 SUM(ITM_QTY) AS 当日使用数量,\n		 GROUP_CONCAT(FEE_DTL_NO) AS 明细编号列表,\n		 GROUP_CONCAT(CHRG_DT) AS 收费时间列表,\n		 GROUP_CONCAT(ITM_QTY) AS 每次数量列表,\n		 GROUP_CONCAT(CRT_STFF_NM),\n		 COUNT(*) AS 收费次数\nFROM FACT_INHOS_FEE_DTL\nWHERE CHRG_ITM_NM = \'外固定架使用\'\n		AND (INVLD_FLG != \'1\')\n		AND ITM_UNT IN (\'日\', \'天\', \'day\', \'Day\')\n		AND MDC_ORG_CD = 5605\n        AND DATE(CHRG_DT) >= \'{{START_DATE}}\'\n        AND DATE(CHRG_DT) <= \'{{END_DATE}}\'\nGROUP BY  INHOS_NO, DATE(CHRG_DT)\nHAVING SUM(ITM_QTY) > 1\nORDER BY  INHOS_NO, 收费日期','','2026-07-22 09:05:47.497610','2026-07-22 09:43:01.715164'),(2,'串换药品','串换','111','SELECT INHOS_NO AS 住院号,\n		 DATE(CHRG_DT) AS 收费日期,\n		 SUM(ITM_QTY) AS 当日使用数量,\n		 GROUP_CONCAT(FEE_DTL_NO) AS 明细编号列表,\n		 GROUP_CONCAT(CHRG_DT) AS 收费时间列表,\n		 GROUP_CONCAT(ITM_QTY) AS 每次数量列表,\n		 GROUP_CONCAT(CRT_STFF_NM),\n		 COUNT(*) AS 收费次数\nFROM FACT_INHOS_FEE_DTL\nWHERE CHRG_ITM_NM = \'外固定架使用\'\n		AND (INVLD_FLG != \'1\')\n		AND ITM_UNT IN (\'日\', \'天\', \'day\', \'Day\')\n		AND MDC_ORG_CD = 5605\n        AND DATE(CHRG_DT) >= \'{{START_DATE}}\'\n        AND DATE(CHRG_DT) <= \'{{END_DATE}}\'\nGROUP BY  INHOS_NO, DATE(CHRG_DT)\nHAVING SUM(ITM_QTY) > 1\nORDER BY  INHOS_NO, 收费日期','','2026-07-22 11:43:16.930387','2026-07-22 11:43:16.930387');
